import type { CitySummary, MonthGuide, Slide, Service } from '@/lib/types'

export const CITIES: CitySummary[] = [{"slug":"abu-dhabi","name":"Abu Dhabi","region":"Middle East","lat":24.457,"lon":54.338,"country":"UAE","tagline":"Stately capital of mosques, museums and quiet luxury.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"3.3h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~4d"}],"months":["peak","peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, Nov and Dec","whenBlurb":"November to March is the only temperate window, and it holds the year's marquee season: the Grand Prix, Frieze, tennis and festival concerts; avoid the severe April-October heat that pushes well into the forties.","lede":"Abu Dhabi is the cultural and unhurried counterpoint to Dubai, and most people give it a rushed day when it deserves two. Prioritise the Louvre and the Sheikh Zayed Grand Mosque, the mosque at dusk, when the white marble turns and the crowds thin, and leave the theme parks on Yas for travellers with children. The real luxury here is space and calm, not spectacle."},{"slug":"agra","name":"Agra","region":"India","lat":27.175,"lon":78.01,"country":"India","tagline":"The Mughal city forever crowned by the Taj Mahal.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"2","small":"days"},{"label":"From India","value":"1h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Oct, Nov and Dec","whenBlurb":"Visit October to March for cool, clear days at the Taj, with February's Taj Mahotsav the cultural high point; escape the April to June furnace and the July to September monsoon haze.","lede":"Agra is a one-night city that most people treat as a half-day, and that is the mistake; stay over so you can be at the Taj Mahal at sunrise and again see it change colour, rather than fighting the midday crowds. Don't neglect Agra Fort and the often-empty 'Baby Taj', and consider Fatehpur Sikri on the way in or out. Choose a hotel with a Taj view; you will thank yourself at dawn."},{"slug":"alleppey","name":"Alleppey","region":"India","lat":9.199,"lon":76.486,"country":"India","tagline":"The Venice of the East amid Kerala's backwaters.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"November to March is the dry, green backwater season for houseboats; the June-September monsoon suits Ayurveda, and August's Onam brings the great snake-boat races.","lede":"Alleppey is the gateway to the Kerala backwaters, and the mistake is treating it as a town, the point is to get onto the water. Take a private houseboat overnight rather than the crowded day cruises, and choose the smaller canals over the wide main lake. Time it for the evening, when the boats moor and the paddy fields go quiet. Late-August boat-race season is spectacular but busy."},{"slug":"amalfi-coast","name":"The Amalfi Coast","region":"Southern Europe","lat":40.64,"lon":14.552,"country":"Italy","tagline":"Vertiginous cliffs, pastel villages and impossibly blue sea.","facts":[{"label":"Best months","value":"May–Jul","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"11.5h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","shoulder","avoid","avoid","avoid","avoid"],"bestMonths":"May, Jun and Jul","whenBlurb":"May-June and September-October are warm, calm and golden; avoid the crowded July-August heat and the November-March shutdown, when many hotels close.","lede":"The Amalfi Coast is best travelled by boat, not by that white-knuckle coast road, hire a gozzo for the day and you'll understand the place in a way the bus tours never will. Positano is the postcard but Ravello, high above the sea, is where you'll actually want to stay: cooler, quieter, and with the two great villa gardens. Come in May or late September; July and August turn the road into a car park and the beaches into a scrum."},{"slug":"amman-petra","name":"Amman & Petra","region":"Middle East","lat":31.893,"lon":35.874,"country":"Jordan","tagline":"Hills of Roman ruins above the road to Petra.","facts":[{"label":"Best months","value":"Mar–Oct","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"6.5h","small":"1 stop"},{"label":"Visa","value":"On arrival","small":null}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","peak","peak","shoulder","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Sep and Oct","whenBlurb":"March to May and October to November bring wildflower deserts, mild Petra walks and Petra by Night's candlelit Treasury; summer bakes the canyons and Amman turns cold in deep winter.","lede":"Treat Amman as the base and Petra as the reason. Give the capital a day for the Citadel and the Roman theatre, then drive the King's Highway south rather than the fast desert road, the wadis and Crusader castles are the point. At Petra, arrive at opening and walk past the Treasury to the Monastery; most people never get that far."},{"slug":"amritsar","name":"Amritsar","region":"India","lat":31.636,"lon":74.879,"country":"India","tagline":"Spiritual heart of the Sikhs around the Golden Temple.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"1h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"Cool, clear winters from October to March are best, with Baisakhi in April and Gurpurab in November lighting the Golden Temple. Avoid the searing summer.","lede":"Amritsar is essentially about two things done exceptionally well: the Golden Temple and the food. See the temple at both night and dawn, when it is quietest and most moving, and eat your way through the old city rather than the hotel restaurants. The Wagah border ceremony is a spectacle but heavily touristy; go if it interests you, but the temple and the Partition Museum are the deeper experiences."},{"slug":"amsterdam","name":"Amsterdam","region":"Western Europe","lat":52.373,"lon":4.892,"country":"Netherlands","tagline":"Golden Age canals, gabled houses and easy sophistication.","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"9.2h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","shoulder","shoulder","shoulder","peak","peak","peak","peak","shoulder","avoid","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"April to June for long light and the tulips, September for calm and mild days. Avoid the grey, wet, dark November-to-February stretch.","lede":"Amsterdam rewards slowness and punishes the checklist. Base yourself in the canal belt, walk or cycle everywhere, and give the big museums their first opening hour rather than the crowded middle of the day. The Jordaan and the quieter southern canals are where the city actually lives; the Red Light District and the coffee-shop trail are what everyone else came for, and you can happily skip both."},{"slug":"andaman","name":"Andaman Islands","region":"India","lat":12.611,"lon":92.832,"country":"India","tagline":"Coral seas, white sands and dense tropical island calm.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"3.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"Come in the dry season, November to April, for calm seas and clear diving; time it to turtle nesting December-March or the January Island Tourism Festival, and avoid the May-to-September monsoon.","lede":"The Andamans are about the water and a small number of exceptional beaches, not a packed island-hopping schedule, so pick one or two islands and stay put rather than churning through ferries. Havelock (Swaraj Dweep) has the famous sand and diving; Neil (Shaheed Dweep) is the quieter one. Do the diving or snorkelling properly with a good operator, and treat the historical Cellular Jail in Port Blair as a meaningful half-day, not an afterthought."},{"slug":"athens","name":"Athens","region":"Southern Europe","lat":37.976,"lon":23.735,"country":"Greece","tagline":"The ancient cradle of democracy beneath the Acropolis.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"7.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","peak","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Sep, Oct and Nov","whenBlurb":"April to June and September into October bring warm, clear days, ancient-theatre nights and Orthodox Easter's drama; skip a half-empty, oppressive July-August when the city decamps to the islands.","lede":"Athens is a summer-evening city, not a midday one. Do the Acropolis at opening or in the last hour before close, then spend the heat of the day indoors at the Acropolis Museum and the National Archaeological Museum, and let the city come alive after dark in Koukaki and Pangrati. Most people give Athens a rushed day and run for the islands; two unhurried nights and a rooftop with a Parthenon view will change their mind."},{"slug":"auckland","name":"Auckland","region":"Oceania","lat":-36.852,"lon":174.763,"country":"New Zealand","tagline":"City of sails between two harbours and green volcanoes.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"17h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~14d"}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"February to March and November to December give warm, settled harbour days, the crimson pōhutukawa bloom and the sailing calendar; skip the wet, cool June-August winter that belongs indoors.","lede":"Auckland is a jumping-off point as much as a destination, and its best hours are spent on or across the water. Give the museum and the Sky Tower a morning, then get out to Waiheke's vineyards or the black-sand west coast, which is where the region actually earns its reputation. The mistake is treating it as a city break; treat it as a base for the Hauraki Gulf and the wine islands instead."},{"slug":"bali","name":"Bali","region":"South-East Asia","lat":-8.227,"lon":115.192,"country":"Indonesia","tagline":"Temple-strewn rice terraces, surf coasts and spiritual calm.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"8","small":"days"},{"label":"From India","value":"8h","small":"1 stop"},{"label":"Visa","value":"On arrival","small":null}],"months":["peak","peak","shoulder","shoulder","shoulder","avoid","avoid","avoid","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"Come April through October for the dry season and clear coast; skip November to March, when heavy afternoon rain settles in.","lede":"Bali is really several islands in one, and the mistake is trying to do all of it; pick two bases and stay put. Ubud for culture and rice terraces, and a southern beach or the Bukit for the coast, is the classic pairing that still works. Avoid the traffic-choked Kuta-Seminyak strip if you can, and if your dates land on Nyepi, embrace it, the whole island shuts in silence and it's extraordinary."},{"slug":"bangkok","name":"Bangkok","region":"South-East Asia","lat":13.752,"lon":100.494,"country":"Thailand","tagline":"Gilded temples, river palaces and endless street feasts.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"4h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"Come November to February, when the air turns cool and dry; skip April's fierce heat and the June-to-October monsoon downpours.","lede":"Bangkok rewards the traveller who slows down and moves by boat and on foot rather than fighting the traffic all day. Do the Grand Palace and Wat Pho early, then let the river and the side-streets carry the rest; the food, from street stalls to Michelin rooms, is the real headline. November to February is the window when the heat eases enough to enjoy being out."},{"slug":"barcelona","name":"Barcelona","region":"Southern Europe","lat":41.383,"lon":2.177,"country":"Spain","tagline":"Gaudi's seaside capital of Catalan art and appetite.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"11h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","peak","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Sep, Oct and Nov","whenBlurb":"Come late May to June or in September for warm seas and lighter crowds; skip the hot, packed July-August peak and time it to a festival like La Merce.","lede":"Barcelona is Gaudí plus a great eating city, and both suffer from crowds, buy timed Sagrada Família tickets weeks ahead and go first thing for the morning light through the east windows. Park Güell is best at opening or last entry. Skip the Ramblas restaurants entirely; the real food is in a Gràcia or Sant Antoni bar most tourists never reach."},{"slug":"bengaluru","name":"Bengaluru","region":"India","lat":12.977,"lon":77.59,"country":"India","tagline":"India's garden city and easy-living tech capital.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"0h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","peak","peak","shoulder","shoulder","shoulder","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, May, Sep, Oct, Nov and Dec","whenBlurb":"Cool, clear November to February is best, framed by the Republic Day flower show. Skip the June-to-September monsoon showers.","lede":"Bengaluru is a city to eat, drink and browse rather than to sightsee; treat it as a comfortable base with excellent weather and use it as the launch point for Coorg, Hampi or a Nandi Hills morning. The old cantonment and the Lalbagh gardens are the genuine pleasures; the traffic is the genuine hazard, so cluster your plans by neighbourhood. Don't over-schedule monuments here."},{"slug":"budapest","name":"Budapest","region":"Northern Europe","lat":47.498,"lon":19.04,"country":"Hungary","tagline":"Imperial grandeur and thermal baths astride the Danube.","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"10.5h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"May, June and September are the balm, warm days, thermal baths, café terraces; come August for Sziget or December for the Christmas markets, and avoid the cold, dark heart of winter.","lede":"Budapest is a thermal-bath city split by the river, and the trick is doing the baths right, go to Széchenyi early morning before the day crowds, or book a private bath session. See the Parliament lit up from the Buda side at night. Skip the ruin-bar tourist crush on weekends; the good ones are quiet on a weeknight."},{"slug":"buenos-aires","name":"Buenos Aires","region":"South America","lat":-34.61,"lon":-58.389,"country":"Argentina","tagline":"A European-grand capital of tango, beef and late nights.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"23.5h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~20d"}],"months":["peak","peak","peak","shoulder","peak","peak","shoulder","shoulder","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, May, Jun, Nov and Dec","whenBlurb":"Autumn in March-April and spring in October-November are finest, with jacaranda purple in November. Avoid the humid January heat.","lede":"Buenos Aires keeps late hours, and fighting that rhythm is the surest way to miss it. Eat at ten, take the milonga after midnight, and reserve mornings for slow walks through Recoleta and Palermo rather than early starts. Skip the staged dinner-tango shows aimed at tour groups; a neighbourhood milonga, even just to watch, is the real thing."},{"slug":"cairo","name":"Cairo","region":"Africa","lat":30.044,"lon":31.236,"country":"Egypt","tagline":"Pyramids, the Nile and a thousand years of empire.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"6.5h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~5d"}],"months":["peak","peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, Nov and Dec","whenBlurb":"Come in the cool months, October to March, for the Pyramids and the Nile; catch the Abu Simbel Sun Festival on February 22 or October 22, and avoid the fierce June-to-August desert heat.","lede":"Cairo rewards patience and an early alarm. See the Pyramids at Giza the moment the site opens, before the heat and the crowds, and give a full unhurried half-day to the Grand Egyptian Museum, which finally does the collection justice. Don't try to cram Islamic Cairo, the Egyptian Museum and Giza into one day; the city is dense and the traffic is real, so slow down and let a good fixer smooth the edges."},{"slug":"cancun","name":"Cancún","region":"North America","lat":21.153,"lon":-86.843,"country":"Mexico","tagline":"Turquoise Caribbean shallows along a coast of Maya antiquity.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"21h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~5d"}],"months":["peak","peak","peak","peak","peak","shoulder","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, May, Nov and Dec","whenBlurb":"December to April is dry, warm and clear; whale sharks arrive in summer, but June to October brings hurricane risk and humidity. Skip spring-break March if crowds deter you.","lede":"Treat Cancun as an airport and a base, not the trip itself. The Hotel Zone is a wall of resorts; the real Yucatán is inland and down the coast, so use it to reach Tulum's ruins, the cenotes, and the quieter beaches of Isla Mujeres and Holbox. Time a summer visit for the whale sharks off Isla Mujeres, which is the one thing here that genuinely can't be done anywhere else."},{"slug":"cape-town","name":"Cape Town","region":"Africa","lat":-33.929,"lon":18.417,"country":"South Africa","tagline":"Table Mountain, two oceans and the winelands at its feet.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"13.5h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~10d"}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"November to March is the warm, dry summer for the mountain, beaches and Winelands harvest; pair it with whale season on the coast from June, and avoid the wet, windy winter in the city itself.","lede":"Watch the mountain, not the clock, Table Mountain and Cape Point are worth doing on the first clear, wind-free morning you get, because the cloud and the southeaster can shut them for days. Base half your stay in town and half out on the winelands or the Cape Peninsula; the two feel like different holidays. The Cape Winelands do a private cellar lunch better than almost anywhere, so build a slow day around one estate rather than rushing four."},{"slug":"cappadocia","name":"Cappadocia","region":"Middle East","lat":38.772,"lon":34.527,"country":"Türkiye","tagline":"Fairy-chimney valleys drifting with dawn balloons.","facts":[{"label":"Best months","value":"May–Aug","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"9.5h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~3d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid","avoid"],"bestMonths":"May, Jun, Jul and Aug","whenBlurb":"Balloons fly nearly year-round, but April to June and September to October give the clearest skies; summer scorches, and winter trades cold for snow-dusted valleys.","lede":"Cappadocia is about the light and the air more than any single sight. The balloon flight at dawn is the reason most people come and it earns the hype, but the valleys on foot at golden hour and a night in a proper cave suite are what stay with you. Base in Uçhisar or Ortahisar rather than busy Göreme, and give it three nights so a weathered-out balloon morning doesn't cost you the whole trip."},{"slug":"chennai","name":"Chennai","region":"India","lat":13.084,"lon":80.27,"country":"India","tagline":"Temple gateways, Carnatic music and a long Bay of Bengal shore.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"1h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"November to February is cool and, in Margazhi, alive with the world's greatest Carnatic music season. Avoid the fierce April to June heat and October monsoon.","lede":"Chennai is a city of temples, music and the sea rather than obvious sights, and it rewards travellers interested in the deep Tamil and Carnatic culture more than casual sightseers. Do the Marina and the San Thome quarter early, and give real time to Mylapore and, ideally, a day trip to the Pallava wonders at Mahabalipuram. The December music season is the reason to time a trip here if culture is your thing."},{"slug":"colombo","name":"Colombo","region":"South Asia & Indian Ocean","lat":6.939,"lon":79.854,"country":"Sri Lanka","tagline":"Sri Lanka's seafront capital, colonial bones and Indian Ocean spice.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":"~2d"}],"months":["peak","peak","shoulder","shoulder","shoulder","avoid","avoid","avoid","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Sep, Oct, Nov and Dec","whenBlurb":"December to March is dry and clear on the west coast, with Galle's literary festival in January; avoid the May–September southwest monsoon.","lede":"Colombo has quietly become worth a stay in its own right rather than just an airport you pass through on the way to the beaches or the hill country. Give it a day and a half: the Dutch-era Fort and Pettah for the mornings, Galle Face Green at dusk with the kite-sellers and isso wade, and dinner in one of the restored Cinnamon Gardens bungalows. Don't overplan it; the pleasure here is walking a compact, humid, layered city and eating extremely well."},{"slug":"copenhagen","name":"Copenhagen","region":"Northern Europe","lat":55.687,"lon":12.57,"country":"Denmark","tagline":"Hygge, design and the world's New Nordic kitchen.","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"8.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~18d"}],"months":["avoid","avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"Come May to August for long white-night days and the July jazz festival; December glows for Tivoli's Christmas market, but expect grey and cold the rest of winter.","lede":"Copenhagen is best taken on two wheels and on foot, at an unhurried pace. Rent a bike, base yourself centrally, and build days around the harbour baths, the food halls and a single great meal rather than a monument checklist. The Little Mermaid is a five-minute disappointment everyone queues for; spend that time in Christianshavn or on a harbour swim instead."},{"slug":"cusco","name":"Cusco & Machu Picchu","region":"South America","lat":-13.164,"lon":-72.545,"country":"Peru","tagline":"The Inca capital and gateway to Machu Picchu's heights.","facts":[{"label":"Best months","value":"Apr–Aug","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"30h","small":"1 stop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["shoulder","shoulder","shoulder","peak","peak","peak","peak","peak","avoid","avoid","shoulder","shoulder"],"bestMonths":"Apr, May, Jun, Jul and Aug","whenBlurb":"Come in the May-to-September dry season for clear skies and Inti Raymi on June 24; avoid the January-to-March rains, and note the Inca Trail closes all February.","lede":"Cusco is where you acclimatise before Machu Picchu, so give it two days at altitude before you climb, the mistake everyone makes is rushing straight up. The city itself is a marvel of Inca stonework under Spanish churches; walk San Blas early. Book Machu Picchu and the train weeks ahead, and consider Rainbow Mountain only once your body has adjusted."},{"slug":"darjeeling","name":"Darjeeling","region":"India","lat":27.038,"lon":88.263,"country":"India","tagline":"Tea gardens, the toy train and Kanchenjunga at dawn.","facts":[{"label":"Best months","value":"Apr–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"4h","small":"1 stop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["shoulder","shoulder","shoulder","peak","peak","peak","shoulder","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Apr, May, Jun, Nov and Dec","whenBlurb":"Spring and autumn give the clearest Kanchenjunga views and the prized tea flushes; skip the June-September monsoon of mist and landslides.","lede":"Darjeeling is about the tea, the toy train and that one clear dawn view of Kanchenjunga, and the honest truth is the mountain hides behind cloud more often than not, so build in enough mornings to catch it. Stay on a working tea estate below the town rather than in the busy Mall area. Come in the clear post-monsoon autumn or the spring; the monsoon buries the views entirely."},{"slug":"delhi","name":"New Delhi","region":"India","lat":28.614,"lon":77.209,"country":"India","tagline":"Mughal grandeur and leafy avenues at India's imperial capital.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"0h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Oct, Nov and Dec","whenBlurb":"October to March is the pleasant season, crowned by the Republic Day parade and Diwali; avoid the May-June furnace and January's smog and fog.","lede":"Delhi is two cities, the Mughal old town and the leafy colonial capital, and you need a day for each. Do Humayun's Tomb over the Red Fort if you have to choose; it's calmer and, many think, more beautiful. Go to Old Delhi early with a guide for the food and the Jama Masjid, and avoid the touts around the big monuments by having a driver and a plan."},{"slug":"doha","name":"Doha","region":"Middle East","lat":25.311,"lon":51.508,"country":"Qatar","tagline":"Gulf capital of bold museums and desert sea.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"3.7h","small":"nonstop"},{"label":"Visa","value":"On arrival","small":null}],"months":["peak","peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, Nov and Dec","whenBlurb":"November to March is the only real window, warm days for the corniche, museums and desert; the jewellery and film weeks and National Day cluster here, and summer is best avoided entirely.","lede":"Doha has become a genuinely serious cultural stop, not just a stopover. Give it two full days: the Museum of Islamic Art is world-class, and the restored Msheireb quarter and the Souq Waqif are best walked in the evening cool. Time a visit around National Day if you can, the waterfront comes alive."},{"slug":"dubai","name":"Dubai","region":"Middle East","lat":25.03,"lon":55.155,"country":"UAE","tagline":"Desert spectacle and skyline glamour at full throttle.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"3.2h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~4d"}],"months":["peak","peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, Nov and Dec","whenBlurb":"Come November to March for temperate days, the racing season and Art Dubai in spring; avoid June to September, when the heat turns severe.","lede":"Dubai rewards travellers who look past the record-breaking numbers and treat the desert and the older creek city as seriously as the towers. Do the marquee sights (Burj Khalifa, the fountains) early or late to dodge both the crowds and the heat, and spend real time in a private desert camp and the Al Fahidi lanes, which is where the place actually breathes. Come between November and March; the summer is genuinely punishing and most outdoor pleasures shut down."},{"slug":"dublin","name":"Dublin","region":"Northern Europe","lat":53.349,"lon":-6.261,"country":"Ireland","tagline":"Georgian grace, literary spirit and warm convivial pubs.","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"11h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~20d"}],"months":["avoid","avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","shoulder","avoid","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"Come May to September for the mildest, brightest days and long evenings; time it to St. Patrick's in March or literary Bloomsday in June, and expect rain in any month.","lede":"Dublin is compact and conversational, its pleasures are literary, musical and social rather than architectural, so the best hours are spent in its bookshops, pubs and along the coast. Do the Book of Kells and a serious literary walk, but resist spending your nights in the Temple Bar crush; the good sessions and pints are in the older pubs the locals actually use. Give a day to the DART line out to Howth or Dalkey, the sea and the walking are half of why people love this city."},{"slug":"dubrovnik","name":"Dubrovnik","region":"Southern Europe","lat":42.649,"lon":18.095,"country":"Croatia","tagline":"The walled Adriatic city of marble streets and sea.","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"16h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~45d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"Come late spring or September for warm seas without the July–August crush; the summer festival is glorious but crowds and cruise ships peak then.","lede":"Dubrovnik is astonishing and completely overrun by midday cruise crowds, so the whole game is timing, walk the walls at opening or after 6pm and have the Old Town almost to yourself. Don't sleep inside the walls unless you love hauling luggage up stone steps; base yourself just outside and walk in. Give it two nights, then take a boat to the quieter islands, which is where the real Dalmatia lives."},{"slug":"edinburgh","name":"Edinburgh","region":"Northern Europe","lat":55.953,"lon":-3.188,"country":"Scotland","tagline":"A dramatic stone capital of castle, crag and Enlightenment.","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"12.5h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~18d"}],"months":["avoid","avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","shoulder","avoid","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"Late spring through early autumn is kindest; August brings the Fringe, International Festival and Tattoo but heaving crowds, and Hogmanay lights up New Year.","lede":"Edinburgh is a city to walk and climb, the pleasure is in its ridges, closes and sudden views, so pack good shoes and give yourself time to wander off the Royal Mile. August turns the whole place into one vast festival, which is exhilarating but crowded and dear; if you want the city calm and the light long, come in late spring or early autumn instead. Climb Arthur's Seat, drink good whisky, and treat the Old Town's tourist tartan shops as scenery, not shopping."},{"slug":"florence","name":"Florence","region":"Southern Europe","lat":43.77,"lon":11.256,"country":"Italy","tagline":"The cradle of the Renaissance, set in Tuscan hills.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"13h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","avoid","shoulder","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Oct and Nov","whenBlurb":"Spring (Apr–Jun) and early autumn (Sept–Oct) are gentlest; skip July and August, when the city turns hot, humid and thick with crowds.","lede":"Florence is small enough to exhaust in a weekend and rich enough to return to for a lifetime, the trick is to book the Uffizi and Accademia the moment you have dates, and to see them first thing so the rest of the day is yours. Everyone climbs the Duomo; fewer walk up to Piazzale Michelangelo or San Miniato at sunset, which is the better view and half the crowd. Cross the river to the Oltrarno for the artisans' workshops, and treat lunch as the meal that matters here."},{"slug":"galle","name":"Galle","region":"South Asia & Indian Ocean","lat":6.033,"lon":80.215,"country":"Sri Lanka","tagline":"A ramparted Dutch fort town, gem of Sri Lanka's south coast.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"3.5h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~2d"}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Oct, Nov and Dec","whenBlurb":"December to March is the south coast at its finest, opening with the Literary Festival in January; avoid the May to September monsoon, when the sea turns rough.","lede":"Galle is a walled Dutch fort you stay inside, not a beach town you drive through, book a room within the ramparts and give it two nights minimum. The pleasure is aimless: the fort walls at sunset, the lighthouse, the antique dealers and small cafés in the old mansions. Skip the packed midday ramparts near the flag; walk the far northern wall instead."},{"slug":"geneva","name":"Geneva","region":"Alpine & Central Europe","lat":46.202,"lon":6.147,"country":"Switzerland","tagline":"Diplomacy, watchmaking and a lake framed by Mont Blanc","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"11h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","shoulder","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"May to September is the season for the lake and the Alps; come in April for Watches and Wonders or mid-December for L'Escalade, and skip the cold, grey heart of winter.","lede":"Geneva is a working international city more than a holiday town, and it repays travellers who lean into the lake, the watchmaking and the surrounding Alps rather than expecting Old-World charm on every corner. Do the old town and a lake crossing, use the city as a base for Mont Blanc and the vineyards of Lavaux, and time a serious meal or a watch appointment if that's your interest. It is expensive and reserved, so keep the pace unhurried."},{"slug":"goa","name":"Goa","region":"India","lat":15.3,"lon":74.086,"country":"India","tagline":"Sun-bleached beaches, Portuguese churches and a barefoot pulse.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"1h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","avoid","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"November to February is golden and dry, the season of Carnival and Sunburn; skip the June to September monsoon unless you want the green, empty version.","lede":"There are two Goas, and the mistake is trying to do both in one trip; pick the quiet, characterful south for beaches and villages, or the livelier north for nightlife and markets. The real Goa beyond the beach is Portuguese-Catholic and Hindu heritage, riverine and green, best seen in the inland villages and the old churches of Panjim and Old Goa. Come in the shoulder weeks either side of peak season for the best of it."},{"slug":"hanoi","name":"Hanoi","region":"South-East Asia","lat":21.028,"lon":105.854,"country":"Vietnam","tagline":"Lakeside temples, French boulevards and old-quarter bustle.","facts":[{"label":"Best months","value":"Apr–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"5.5h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~4d"}],"months":["shoulder","shoulder","shoulder","peak","peak","shoulder","shoulder","shoulder","avoid","shoulder","peak","peak"],"bestMonths":"Apr, May, Nov and Dec","whenBlurb":"Autumn, September to November, is the city at its finest: warm sun, dry air, mild light. Skip the wet summer heat and grey, damp winter.","lede":"Give Hanoi more time than people assume, its pleasures are slow and best taken on foot, ideally at dawn when the lakes belong to tai chi practitioners and the pho stalls are at their sharpest. Skip the packaged water-puppet show and the frantic Old Quarter shopping; the real city is in the crumbling French villas of Ba Dinh, the egg-coffee balconies, and a long lunch of bun cha where Obama once sat. The weather makes or breaks a trip: come in autumn (October–November) for dry, cool days, and avoid the grey drizzle of February and March."},{"slug":"ho-chi-minh-city","name":"Ho Chi Minh City","region":"South-East Asia","lat":10.774,"lon":106.717,"country":"Vietnam","tagline":"French colonial relics meet frenetic, neon-lit energy.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"4.5h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~4d"}],"months":["peak","peak","peak","shoulder","shoulder","shoulder","shoulder","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"Come December to April for dry, bright days; time it with Tet in February for the city at its most festive, and brace for daily downpours from May to October.","lede":"Saigon rewards appetite and energy more than sightseeing, the War Remnants Museum and the Reunification Palace are worth a serious half-day, but the city's real pleasure is at the table and on the street after dark. Base yourself in District 1 for a first visit, then cross into District 3 or Binh Thanh for the food locals actually queue for. Don't try to see it from a bus; the heat and the traffic mean the best moves are short, deliberate, and broken up by a good rooftop."},{"slug":"hoi-an","name":"Hoi An & Da Nang","region":"South-East Asia","lat":15.88,"lon":108.332,"country":"Vietnam","tagline":"Lantern-lit heritage town beside Da Nang's golden coast.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"7h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~4d"}],"months":["peak","shoulder","shoulder","shoulder","avoid","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Nov and Dec","whenBlurb":"February to May is dry and pleasant, with the lantern festival glowing on every full moon; October and November bring the wettest months and real flood risk.","lede":"Treat Hoi An and Da Nang as one trip with two moods, the old town for lantern-lit evenings and tailors, Da Nang and its beaches for space, seafood and a proper resort base. See the old town at dawn or after the day-trippers leave; in the middle of the day it's a crush. The Marble Mountains and My Son are the day-trips that actually earn the drive, and the beach between the two cities is where you should be sleeping."},{"slug":"hong-kong","name":"Hong Kong","region":"East Asia","lat":22.282,"lon":114.158,"country":"Hong Kong","tagline":"Vertical glamour where harbour, peak and dim sum meet.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"5.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":"~2d"}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Sep, Oct, Nov and Dec","whenBlurb":"October through December is dry, clear and comfortable; March brings the art season. Skip the humid, typhoon-prone June-to-September stretch.","lede":"Hong Kong is best read as three cities stacked together: the harbour, the Peak-side mid-levels, and the outlying islands, and you should give at least a day to the last of these, which most visitors skip entirely. Take the Star Ferry rather than the tunnel at least once, eat dim sum before ten, and don't let the shopping malls swallow the trip; the real texture is in the wet markets, the ferry piers, and the trails that start ten minutes from the towers. Kowloon-side hotels give you the better skyline view; Hong Kong Island puts you closer to the restaurants."},{"slug":"hyderabad","name":"Hyderabad","region":"India","lat":17.361,"lon":78.474,"country":"India","tagline":"Nizam splendour, biryani and a thriving tech metropolis.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"1.2h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak","peak"],"bestMonths":"Jan, Feb, Oct, Nov and Dec","whenBlurb":"October to February is the pleasant window, from Bathukamma's flowers to winter's Numaish fair; avoid the parched April-to-June heat.","lede":"Hyderabad is a Nizam city that few outsiders read properly, it's biryani, pearls and Qutb Shahi grandeur, not an IT park. See the Charminar and the old city early, then give real time to the Golconda Fort at sunset for the light and the sound-and-light show. Skip the mall version of Hyderabadi food and eat the real biryani where the old families do; the Chowmahalla Palace is the underrated star."},{"slug":"istanbul","name":"Istanbul","region":"Middle East","lat":41.006,"lon":28.976,"country":"Türkiye","tagline":"Where Europe meets Asia across the Bosphorus straits.","facts":[{"label":"Best months","value":"May–Aug","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"7.5h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~3d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid","avoid"],"bestMonths":"May, Jun, Jul and Aug","whenBlurb":"April for the tulips and gentle warmth, or September into October when the Bosphorus cools and light turns amber; avoid the crowded July-August heat and the grey, wet winter.","lede":"Give the city three nights and split them by shore, the old-city monuments on the historic peninsula, then a night or two on the Bosphorus for the modern, waterside Istanbul most visitors miss. See Hagia Sophia and the Blue Mosque early, then spend the afternoon on the water; a ferry or private boat up the strait tells you more about the city than any museum. Skip the Grand Bazaar's front stalls and go deep, or better, to the quieter Arasta and spice markets."},{"slug":"jaipur","name":"Jaipur","region":"India","lat":26.915,"lon":75.819,"country":"India","tagline":"The pink city of Rajput palaces, bazaars and forts.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"1h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Oct, Nov and Dec","whenBlurb":"The cool, clear October-to-February window is Jaipur's season, crowned by the January literature festival. Avoid the scorching summer and soft monsoon light.","lede":"Jaipur repays slowing down; the palaces are best in the first two hours after opening, and the walled Pink City is a morning proposition before the heat and crowds. Don't buy the tourist-trap gem 'factory' visits; do seek out the genuine block-printers, blue-pottery and jewellery ateliers. Stay in a restored haveli or palace hotel rather than a generic property, because here the lodging is half the experience."},{"slug":"jaisalmer","name":"Jaisalmer","region":"India","lat":27.026,"lon":70.778,"country":"India","tagline":"The golden fort-city rising from the Thar desert.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"October to February is the only comfortable window, and early February crowns it with the Desert Festival on the Sam dunes; avoid the extreme desert summer entirely.","lede":"Jaisalmer is the one living fort in India where people still reside inside the walls, so treat the citadel gently and consider staying in a restored haveli in town rather than inside the stressed fort itself. The point of coming is the desert; give a night to a proper dune camp away from the crowded Sam strip. Come in winter; the summer heat here is genuinely punishing."},{"slug":"jodhpur","name":"Jodhpur","region":"India","lat":26.297,"lon":73.035,"country":"India","tagline":"The blue city beneath Rajasthan's mightiest hill fort.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Oct, Nov and Dec","whenBlurb":"Come in the cool winter, October to February, for clear desert light and the great fort festivals; avoid the fierce April-June heat entirely.","lede":"Jodhpur is really about one extraordinary fort and the blue city beneath it, so give the mornings to Mehrangarh and the late afternoons to wandering the indigo lanes of the old town. The rooftop-cafe view of the fort is worth chasing, but the fort itself, seen early, is the reason to come. Pair it with a night at a heritage palace and, if you have time, a village safari into the Bishnoi country."},{"slug":"kathmandu","name":"Kathmandu","region":"South Asia & Indian Ocean","lat":27.708,"lon":85.321,"country":"Nepal","tagline":"A Himalayan valley of gilded temples, stupas and living heritage.","facts":[{"label":"Best months","value":"Mar–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"1.7h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","avoid","avoid","peak","peak","peak"],"bestMonths":"Mar, Apr, May, Jun, Oct, Nov and Dec","whenBlurb":"Come October-November or March-April for clear skies, mountain views and the great autumn festivals of Dashain and Tihar; skip the June-September monsoon and January's cold.","lede":"Base yourself in Patan, not touristy Thamel, the Durbar Square there is the most intact of the three and you'll sleep better. Give the valley its due: Bhaktapur, Boudhanath and Pashupatinath each deserve half a day, and the drive out to Nagarkot for a Himalayan sunrise is worth the early start. The city rewards patience over ticking sights, so slow down and let the courtyards find you."},{"slug":"kochi","name":"Kochi","region":"India","lat":9.968,"lon":76.244,"country":"India","tagline":"Spice-trade port where colonial Kerala meets the sea.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"October to March is dry and pleasant, with the Biennale and Cochin Carnival crowning winter; avoid the heavy June-September monsoon downpours.","lede":"Kochi is the most walkable and cosmopolitan corner of Kerala, and Fort Kochi deserves a slow two days on foot rather than a rushed stopover before the backwaters. Time your first evening for the Chinese fishing nets at sunset, but spend the days in the spice-trade lanes, the churches and synagogue, and the excellent contemporary art spaces. It is a good soft landing before or after the houseboats."},{"slug":"kolkata","name":"Kolkata","region":"India","lat":22.573,"lon":88.364,"country":"India","tagline":"Colonial grandeur, Bengali arts and unhurried intellectual soul.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"2.2h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"The cool, dry winter from November to February is the city at its finest, crowned by October's Durga Puja; sidestep the sticky summer and the July-to-September monsoon.","lede":"Kolkata is India's most literary and soulful big city, and it rewards walking, conversation and coffee-house afternoons more than any monument checklist. Do the colonial core and the north-Kolkata lanes with a good guide, give real time to the food and the sweet shops, and, if you possibly can, time your visit to Durga Puja. Skip the rush; the city's pleasure is in lingering."},{"slug":"krabi","name":"Krabi","region":"South-East Asia","lat":8.063,"lon":98.916,"country":"Thailand","tagline":"Towering karsts, jade waters and tranquil Andaman shores.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"7h","small":"1 stop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"November to March brings dry days, calm seas and clear rock; the May-October monsoon means heavy rain and rough water for island-hopping.","lede":"Krabi is the calmer, more scenic alternative to Phuket, and its best assets are offshore, so build the trip around the water. Base yourself on the quieter beaches or a private island rather than busy Ao Nang, and get onto the sea early to beat the crowds to Railay and the Hong islands. November to March is the dry, clear window; the monsoon months turn the sea rough and the boats unreliable."},{"slug":"kuala-lumpur","name":"Kuala Lumpur","region":"South-East Asia","lat":3.152,"lon":101.694,"country":"Malaysia","tagline":"Twin towers, colonial arcades and a melting-pot table.","facts":[{"label":"Best months","value":"Jan–Nov","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"4.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","shoulder","peak","shoulder","shoulder","shoulder","shoulder","peak","shoulder","peak","peak","shoulder"],"bestMonths":"Jan, Mar, Aug, Oct and Nov","whenBlurb":"Tropical year-round with afternoon rain; May to July and December to February are the steadier windows around the great Thaipusam and Deepavali festivals.","lede":"Kuala Lumpur is underrated as a food and heritage stop and overrated as a skyline photo, see the Petronas Towers, then get out into the old shophouse quarters and the hill temples. The Batu Caves are worth the early start to beat the heat and the crowds on the 272 steps. KL is also the easy launchpad for the tea highlands and the islands, so don't overstay in the centre."},{"slug":"kyoto","name":"Kyoto","region":"East Asia","lat":35.012,"lon":135.768,"country":"Japan","tagline":"Imperial temples, tea ritual and lacquered restraint.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"11.5h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~6d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","avoid","avoid","shoulder","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Oct and Nov","whenBlurb":"Come for cherry blossom in early April or the koyo autumn colour of mid-to-late November; skip the hot, humid rains of June to August.","lede":"Base yourself here for at least three nights and treat the famous temples as dawn or dusk affairs, Fushimi Inari and Arashiyama's bamboo are transformed before 7am and unbearable by ten. The real Kyoto is in its ryokan dinners, tea houses and the machiya backstreets of the north, not the coach-park headline sights. Skip the packaged 'geisha spotting' in Gion; book a proper ozashiki evening through your hotel instead."},{"slug":"lake-como","name":"Lake Como","region":"Southern Europe","lat":45.992,"lon":9.265,"country":"Italy","tagline":"Italy's most aristocratic lake, ringed by villa gardens.","facts":[{"label":"Best months","value":"Apr–Aug","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"9.75h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~18d"}],"months":["avoid","avoid","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","avoid","avoid"],"bestMonths":"Apr, May, Jun, Jul and Aug","whenBlurb":"May-June for gardens in bloom and September for warm, softer light; skip humid, crowded August, and expect a shuttered, misty quiet in deep winter.","lede":"Como is a lake to be lived on the water and in the villa gardens, not driven around, the roads are slow and blind, so base yourself well and travel by private launch. Bellagio gets the crowds and the fame, but the western shore around Lenno and Tremezzo has the great villas and the best light, while the quiet Lecco arm suits those who want the mountains to themselves. Stay into the evening after the day-trippers leave; the lake at dusk is the whole point."},{"slug":"langkawi","name":"Langkawi","region":"South-East Asia","lat":6.37,"lon":99.793,"country":"Malaysia","tagline":"Rainforest-clad isles, mangroves and tranquil Andaman beaches.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"6.5h","small":"1 stop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","shoulder","shoulder","shoulder","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"Come December to March for the driest, calmest seas and clearest cable-car views; skip the wetter July-October monsoon months of rougher water and afternoon storms.","lede":"Langkawi is quieter and greener than Malaysia's beach reputation suggests, the draw is the rainforest and the Andaman Sea more than the nightlife. Base yourself on the west coast for the sunsets, keep one morning free for the mangroves rather than another beach, and don't skip the cable car up Gunung Mat Cincang for the sky bridge. The island's duty-free status means good wine costs almost nothing; the real luxury is a private boat, not a busy beach."},{"slug":"las-vegas","name":"Las Vegas","region":"North America","lat":36.176,"lon":-115.137,"country":"USA","tagline":"Neon desert spectacle of appetite, chance and showmanship.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"19h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~120d"}],"months":["peak","peak","shoulder","shoulder","peak","peak","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, May, Jun, Nov and Dec","whenBlurb":"March-April and October-November bring desert comfort and a packed calendar of racing, rodeo and Sphere residencies; the brutal summer heat is best kept to the pool, and New Year turns the Strip into the world's largest party.","lede":"Vegas rewards a clear plan and a short stay, decide whether you're here for the tables, the restaurants and shows, or the desert beyond, because trying to do all three blurs into exhaustion. The genuine luxury is off the casino floor: a great meal, a residency show, and a day trip to red rock or the canyon. Two or three nights is plenty; the Strip loses its charm faster than most expect."},{"slug":"leh-ladakh","name":"Leh-Ladakh","region":"India","lat":34.164,"lon":77.585,"country":"India","tagline":"High-desert moonscape of monasteries and turquoise lakes.","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["avoid","avoid","avoid","avoid","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"June to September is the only real window, crowned by the Hemis festival in early summer; passes and roads close in winter, so acclimatise carefully for altitude.","lede":"The single most important thing in Ladakh is to slow down for altitude; give the first two days to acclimatising in Leh before any high pass or lake, because rushing to Pangong on day one is how trips go wrong. Go for the monasteries and the raw high-desert landscape, not a checklist of viewpoints. The season is short, roughly May to September; outside it, most passes and lakes are cut off."},{"slug":"lima","name":"Lima","region":"South America","lat":-12.046,"lon":-77.031,"country":"Peru","tagline":"A Pacific capital crowned by the world's finest kitchens.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"25h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~10d"}],"months":["peak","peak","peak","shoulder","shoulder","shoulder","shoulder","shoulder","shoulder","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Oct, Nov and Dec","whenBlurb":"December to April is bright, warm and beach-ready; May to November brings the grey garua fog, though October's processions and the food calendar reward a visit.","lede":"Lima is a food city first, most people rush it on the way to Cusco and miss the point entirely. Give it two full days, base in Barranco or Miraflores on the cliff, and build the trip around lunch tables rather than sights. The Historic Centre is worth one focused morning; the rest of your time belongs to the coast and the kitchens."},{"slug":"lisbon","name":"Lisbon","region":"Southern Europe","lat":38.708,"lon":-9.137,"country":"Portugal","tagline":"Hills, tiles and Atlantic light over the river Tagus.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"12.5h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","peak","peak","shoulder","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Jul, Aug, Oct and Nov","whenBlurb":"Late spring for jacaranda haze and June's saints' revelry, or September's warm calm; avoid the July-August crush and the grey wet of December-February.","lede":"Lisbon is a city of viewpoints and gradients, best taken slowly and on foot, with the trams saved for when your legs give out rather than as the main event. Prioritise Alfama's tangle of lanes, a genuine fado house at night, and a day out to Sintra; skip the queue for the Santa Justa lift when the same view is free two minutes' walk away. Eat late, drink the vinho verde, and let the light do the work at dusk."},{"slug":"london","name":"London","region":"Western Europe","lat":51.507,"lon":-0.128,"country":"United Kingdom","tagline":"Imperial grandeur and restless reinvention along the Thames.","facts":[{"label":"Best months","value":"Jun–Sep","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"9h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~21d"}],"months":["avoid","shoulder","shoulder","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"Jun, Jul, Aug and Sep","whenBlurb":"Come late May through July for gardens, tennis and the racing calendar, or September for Frieze and fashion; skip the grey, wet depths of December to February.","lede":"London rewards depth over breadth, pick two neighbourhoods and live in them rather than sprinting between landmarks. The great museums are free and best in the first hour after opening; save the blockbuster shows for a members' hour. Skip the tourist afternoon teas on the strand and book a proper one at a hotel that has done it for a century."},{"slug":"los-angeles","name":"Los Angeles","region":"North America","lat":34.139,"lon":-118.354,"country":"USA","tagline":"Sun-drenched sprawl of cinema, ocean and reinvention.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"17h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~30d"}],"months":["peak","peak","peak","peak","peak","peak","peak","peak","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, May, Jun, Jul, Aug, Nov and Dec","whenBlurb":"Warm and dry most of the year, with spring and autumn the sweet spots; time it to jacaranda bloom, gray-whale migration or the awards-and-art season, and only the deep-summer smog and heat give pause.","lede":"Los Angeles punishes people who try to see all of it, pick a base, stay in its orbit, and accept that the drive between two points defines the day. The real texture is in the neighbourhoods and the food, not the tourist Walk of Fame, which you can skip entirely. Time in the canyons, on the coast at Malibu and in a good restaurant will tell you more about the city than any landmark."},{"slug":"madrid","name":"Madrid","region":"Southern Europe","lat":40.424,"lon":-3.69,"country":"Spain","tagline":"Spain's grand capital of art, terraces and golden light.","facts":[{"label":"Best months","value":"May–Aug","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"13.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~20d"}],"months":["shoulder","shoulder","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","shoulder","shoulder"],"bestMonths":"May, Jun, Jul and Aug","whenBlurb":"Spring and early autumn are ideal, April to June and September to October; avoid July and August when the city empties and bakes.","lede":"Madrid rewards those who move at its own hours: skip the morning rush at the big museums and go late, then let the city open up over a long lunch and an even longer night. The Prado and Reina Sofía are the anchors, but the real city is in its plazas, its markets, and its unhurried bar culture, so leave room for wandering rather than ticking boxes. Base yourself centrally and treat the day trips to Toledo or Segovia as optional, not obligatory."},{"slug":"mahe-seychelles","name":"Mahé","region":"South Asia & Indian Ocean","lat":-4.684,"lon":55.493,"country":"Seychelles","tagline":"Granite-boulder beaches and jungle peaks on the Indian Ocean.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"6h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Sep, Oct, Nov and Dec","whenBlurb":"April-May and October-November bring the calmest seas and clearest skies between the trade winds; expect windier water and swell at the height of each monsoon.","lede":"Mahé is where you land and where you should linger a day or two, but the Seychelles reveal themselves on Praslin and La Digue, plan the inter-island hops in. On Mahé itself, trade Beau Vallon's crowds for the harder-to-reach south, Anse Intendance and Petite Anse are the beaches you'll remember. Rent a car and do the cross-island mountain road; the Morne Seychellois forest is the island's overlooked half."},{"slug":"male-maldives","name":"Malé & the Atolls","region":"South Asia & Indian Ocean","lat":4.178,"lon":73.517,"country":"Maldives","tagline":"Overwater villas and luminous lagoons across scattered coral atolls.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"2.1h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","peak","shoulder","shoulder","avoid","avoid","shoulder","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, Oct, Nov and Dec","whenBlurb":"Come November to April for dry, glass-calm seas and warm nights; skip May to October, when the southwest monsoon roughens the water and greys the sky.","lede":"Skip Malé itself beyond a half-day for the fish market and Hukuru Miskiy; the reason you come is the water, so spend on the atolls, not the capital. Choose one resort island and stay put rather than hopping, the seaplane transfer is half the magic, and a good house reef beats any excursion. The quiet play is a liveaboard through the Baa or Ari atolls if you actually want the diving, not just the pool."},{"slug":"manali","name":"Manali","region":"India","lat":32.245,"lon":77.187,"country":"India","tagline":"Snow peaks, apple orchards and the rushing Beas river.","facts":[{"label":"Best months","value":"May–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["shoulder","shoulder","shoulder","shoulder","peak","peak","shoulder","avoid","avoid","shoulder","peak","peak"],"bestMonths":"May, Jun, Nov and Dec","whenBlurb":"Come March to June for green valleys and open passes, or October for apple harvest, Kullu Dussehra and the first snow; skip the July-August monsoon landslides.","lede":"Manali splits sharply between the overrun main town and the quiet, beautiful Old Manali and the villages up the valley, so stay in the latter. Use it as a base for the high passes and the Spiti or Sissu side rather than the town's tourist strip. Timing is everything: the Rohtang and Atal Tunnel access, the snow, and the road to Spiti all depend on season, so plan around what's open."},{"slug":"marrakech","name":"Marrakech","region":"Africa","lat":31.626,"lon":-7.989,"country":"Morocco","tagline":"Rose-red ramparts, palm gardens and the artisan's hand.","facts":[{"label":"Best months","value":"Mar–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"17h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~3d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid","shoulder","peak","peak"],"bestMonths":"Mar, Apr, May, Jun, Nov and Dec","whenBlurb":"Spring and autumn are the season, mild days for gardens and riads; time it to the December film festival or the May rose harvest, and avoid the July-August furnace.","lede":"A riad inside the medina is the only way to understand the city, thick walls, a still courtyard, and the souks a two-minute walk from your door. Do the Jemaa el-Fnaa at dusk when the food stalls light up, not in the flat midday heat, and give the snake charmers a wide berth. Balance the medina's intensity with a day at a garden or a palmeraie estate; the contrast is the pleasure of the place."},{"slug":"mauritius-city","name":"Mauritius","region":"South Asia & Indian Ocean","lat":-20.276,"lon":57.57,"country":"Mauritius","tagline":"Indian Ocean island of lagoons, sugar fields and Creole flavour.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"6.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak","peak"],"bestMonths":"Jan, Feb, Oct, Nov and Dec","whenBlurb":"The cool, dry winter of May to November is calmest and clearest; avoid the January-March cyclone season, when heat and rain peak.","lede":"Mauritius is more than a honeymoon beach, go south and west for the wild coast and the Chamarel country rather than only the manicured north. Base by the sea but rent a car for a couple of days; the Black River gorges, tea country and Grand Bassin are the island's soul. Eat where Mauritians eat, the street dholl puri and a proper table d'hôte beat any resort buffet."},{"slug":"melbourne","name":"Melbourne","region":"Oceania","lat":-37.814,"lon":144.963,"country":"Australia","tagline":"Laneway coffee, the arts and Australia's finest tables.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"12h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~20d"}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"Autumn and spring are kindest, bookended by the Australian Open in January and the Spring Racing Carnival in November; the city is famous for four seasons in a day.","lede":"Melbourne hides itself on purpose, the good coffee, bars and shops are down the laneways and up the stairs, not on the main streets. Give it to walking, eating and the arts rather than a checklist, and let the neighbourhoods do the talking. The one thing worth building a trip around is a major event; the sport and festival calendar here is genuinely world-class."},{"slug":"mexico-city","name":"Mexico City","region":"North America","lat":19.321,"lon":-99.151,"country":"Mexico","tagline":"A high-altitude capital of grand boulevards and world-class kitchens.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"21h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["peak","shoulder","peak","peak","peak","peak","shoulder","shoulder","shoulder","peak","peak","peak"],"bestMonths":"Jan, Mar, Apr, May, Jun, Oct, Nov and Dec","whenBlurb":"Come in the dry season, November to April; time it to Day of the Dead in early November, the jacaranda bloom in spring, or the Zona Maco art fair, and skip the June-September rains.","lede":"Mexico City is one of the world's great food and art capitals and deserves more than a stopover, base in Roma or Condesa and walk. Reserve the big restaurants weeks ahead; the wait for Pujol or Quintonil is real. Go to Teotihuacán early to beat the heat and crowds, and don't miss the Frida Kahlo house, but book its timed ticket in advance."},{"slug":"miami","name":"Miami","region":"North America","lat":25.771,"lon":-80.294,"country":"USA","tagline":"Tropical Art Deco glamour where Latin America meets the sea.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"19h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~30d"}],"months":["peak","peak","peak","peak","peak","shoulder","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, May, Nov and Dec","whenBlurb":"November to April is warm, dry and in full swing, from Art Basel in December to the March music and tennis weeks; summer is hot, humid and hurricane-prone.","lede":"Miami is two cities, the beach and the mainland, and the interesting one is increasingly the mainland: the Design District, Wynwood, and the Cuban weight of Little Havana. Use South Beach for the Art Deco architecture and a swim, but base yourself with intent rather than defaulting to the ocean-front strip. The heat and humidity are real; the season that matters runs roughly November to April."},{"slug":"milan","name":"Milan","region":"Southern Europe","lat":45.464,"lon":9.19,"country":"Italy","tagline":"Italy's capital of fashion, design and quiet wealth.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"8.7h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","avoid","shoulder","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Oct and Nov","whenBlurb":"Spring and early autumn are ideal, framed by the Fashion Weeks and April's Design Week; August empties out and much closes, and winters run foggy.","lede":"Milan is a working luxury city, not an open-air museum, its pleasures are the shops, the aperitivo hour and one or two great sights done properly. Book Leonardo's Last Supper weeks ahead; it is the one thing you cannot walk up to. Skip the crowded Duomo rooftop queue at midday and go at opening, then spend the evening in the Brera lanes."},{"slug":"mumbai","name":"Mumbai","region":"India","lat":19.055,"lon":72.869,"country":"India","tagline":"India's restless maximum city of sea, cinema and commerce.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"0h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"November to February is cool, dry and social; the June-September monsoon is dramatic but drenching, and April-May turns humid and heavy.","lede":"Mumbai is a night-and-morning city; do the sea-facing walks and the dabbawala-era south at dawn, then let the evening belong to its restaurants and bars, which are among the best in the country. Don't waste a day on the crowded 'Bollywood tour' circuit; the real texture is in the Fort district's architecture and the fishing-village edges. Base yourself in the south, not the suburbs, unless you have a specific reason."},{"slug":"munich","name":"Munich","region":"Alpine & Central Europe","lat":48.137,"lon":11.575,"country":"Germany","tagline":"Bavarian capital of beer gardens, baroque and effortless wealth","facts":[{"label":"Best months","value":"Apr–Sep","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"8.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","shoulder","shoulder","peak","peak","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"Apr, May, Jun, Jul, Aug and Sep","whenBlurb":"Beer gardens and long light make May to July golden; come late September for Oktoberfest or December for the Christkindlmarkt, and avoid the grey depths of January and February.","lede":"Munich is Germany at its most comfortable, green, prosperous and easygoing, and it works best as a base for both the city and the Alps an hour south. Give the beer halls a night but don't stop there; the real pleasures are the Englischer Garten, the museum quarter and the food markets. If you come for Oktoberfest, book everything far ahead and know the city is fuller and pricier; for a truer sense of the place, the strong-beer season in Lent or a bright autumn week is more rewarding."},{"slug":"munnar","name":"Munnar","region":"India","lat":10.087,"lon":77.06,"country":"India","tagline":"Rolling tea estates high in the Western Ghats.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"2.5h","small":"1 stop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","shoulder","shoulder","shoulder","shoulder","shoulder","shoulder","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"September to March is cool, green and clear across the tea country; the southwest monsoon closes in from June to August, and the rare Neelakurinji bloom returns around 2030.","lede":"Munnar is a landscape rather than a sightseeing town, so resist the packaged 'point-to-point' viewpoint circuit that clogs the roads and instead stay high on a working tea estate and walk. The mornings, before the valley mist burns off, are the magic; the afternoons often cloud over. Skip the crowded central town and the manufactured 'photo points'; the real Munnar is the silence of the plantations."},{"slug":"muscat","name":"Muscat","region":"Middle East","lat":23.612,"lon":58.594,"country":"Oman","tagline":"Serene Arabian coast of forts, wadis and white minarets.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"2.8h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~4d"}],"months":["peak","peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, Nov and Dec","whenBlurb":"Come October to March, mild and pleasant, and time it to the January Muscat Festival; for the green Khareef monsoon head south to Salalah July-August, and avoid Muscat's May-to-September heat.","lede":"Muscat is the antidote to the Gulf's glass towers, low white buildings, a real corniche, and mountains that fall straight into the sea. Don't treat it as a one-night stop; base here and drive out to the wadis and Nizwa. Skip the beach-resort bubble and spend a night in the Hajar mountains instead."},{"slug":"mykonos","name":"Mykonos","region":"Southern Europe","lat":37.451,"lon":25.392,"country":"Greece","tagline":"Cycladic glamour, windmills and the Aegean's liveliest shores.","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"11h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","avoid","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"This is a scene, not a calendar: come late May to September when the beach clubs and dinners run at full tilt, peaking July-August; the island all but closes in winter.","lede":"Mykonos is two islands at once: the polished beach-club and party circuit, and a quieter Cycladic island of white lanes, windmills and little churches that most visitors barely see. Decide which one you came for. If it's the scene, base near town and book the beach clubs ahead; if it's the calm, take a boat to Delos, eat at the far tavernas, and treat the crowds in Little Venice as a sunset ritual to visit once, not live in."},{"slug":"nairobi-mara","name":"Nairobi & the Mara","region":"Africa","lat":-1.283,"lon":36.964,"country":"Kenya","tagline":"Kenya's vivid capital and the legendary Mara plains.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"6.3h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~3d"}],"months":["peak","peak","shoulder","shoulder","avoid","shoulder","shoulder","peak","peak","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Aug, Sep, Nov and Dec","whenBlurb":"July to October for the Great Migration river crossings, January to February for calving and clear skies. Avoid the long rains of April and May.","lede":"Nairobi is a working city, not a sight to linger over, treat it as the hinge between arrival and the Mara, one or two nights to reset. The move that separates a good trip from an ordinary one is basing inside a private conservancy bordering the reserve rather than the main reserve itself, where you trade shared roads and vehicle jams for off-road driving, night drives and walking. Fly to camp; the road transfer eats a day you don't have."},{"slug":"new-york","name":"New York","region":"North America","lat":40.751,"lon":-73.969,"country":"USA","tagline":"Ambition, art and appetite, all at once, all night.","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"15.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~180d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"Come late spring (May–June) or early autumn (Sept–Oct) for the city at its finest; skip the humid deep summer and the January freeze.","lede":"New York is a city of neighbourhoods, not landmarks; pick a base with a good coffee and a good bar and let the blocks around it be the trip. Book the restaurant of the moment weeks ahead and see one great museum properly rather than three in a blur, the Met alone is a full, unhurried day. Skip Times Square beyond a single glance and give the time instead to the West Village, the High Line at dawn, and the outer-borough tables the guidebooks miss."},{"slug":"nice-riviera","name":"Nice & the Riviera","region":"Western Europe","lat":43.7,"lon":7.268,"country":"France","tagline":"Belle Époque glamour along the azure Mediterranean coast.","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"11h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","avoid","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"Warm sea and calmer crowds in late spring and September; February brings Carnival and citrus. July-August is hot, brilliant and busy.","lede":"Nice is the right base for the Riviera, better value and more real life than Cannes or Monaco, and everything is a short train ride away. Skip the pebble beach for the old town and the Cimiez hills; the daily Cours Saleya market and a Niçoise lunch beat any beach club. Use the coastal train as your car: Villefranche, Èze and Menton are all quick hops, and the corniche drives are the day out worth renting for."},{"slug":"osaka","name":"Osaka","region":"East Asia","lat":34.694,"lon":135.501,"country":"Japan","tagline":"Japan's exuberant kitchen, neon-lit and warm-hearted.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"10h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~7d"}],"months":["shoulder","shoulder","peak","peak","peak","shoulder","avoid","avoid","peak","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Sep, Oct and Nov","whenBlurb":"Cherry blossom in early April and crisp maples in November are finest; time a July visit to Tenjin Matsuri, but skip the hot, humid deep summer.","lede":"Osaka is where you come to eat, so plan around meals rather than monuments and let the castle be a morning aside, not the point. Dotonbori is worth seeing once for the spectacle, but the better food is a street or two back in Shinsekai and the covered arcades, and the standing counters reward anyone willing to point and sit. Use it as a base for Kyoto and Nara by day and give the evenings entirely to the kitchens."},{"slug":"paris","name":"Paris","region":"Western Europe","lat":48.853,"lon":2.348,"country":"France","tagline":"Light on the Seine, a table for every hour, elegance worn lightly.","facts":[{"label":"Best months","value":"May–Aug","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"9h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","shoulder","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","shoulder","avoid"],"bestMonths":"May, Jun, Jul and Aug","whenBlurb":"Come late May through June for long light, Roland-Garros and the couture calendar, or September into October for the art season; skip a shuttered, sweltering August and grey January.","lede":"Give Paris more mornings than you think you need, the Louvre before ten, the Marais before the shops open, a café before the city fills. The great mistake is treating it as a checklist of monuments; the real pleasure is a single arrondissement walked slowly, one long lunch, and the light going gold over the rooftops around seven. Skip the Champs-Élysées entirely and eat where the waiters don't speak English."},{"slug":"paro","name":"Paro & Thimphu","region":"South Asia & Indian Ocean","lat":27.471,"lon":89.638,"country":"Bhutan","tagline":"Himalayan valleys of dzongs, prayer flags and cliffside monasteries.","facts":[{"label":"Best months","value":"Mar–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"2.5h","small":"nonstop"},{"label":"Visa","value":"On arrival","small":null}],"months":["avoid","avoid","peak","peak","peak","peak","shoulder","shoulder","avoid","avoid","peak","peak"],"bestMonths":"Mar, Apr, May, Jun, Nov and Dec","whenBlurb":"Spring and autumn are clear and mild; late September to November offers the crispest Himalayan views. A daily sustainable-tourism fee applies year-round.","lede":"Don't rush Bhutan, the tariff means every day costs, so linger rather than cramming dzongs. Paro and Thimphu are the gentle entry; save your legs and lungs for the climb to Tiger's Nest and do it early, ideally acclimatised after a day or two. Time a trip to a tshechu if you can, but even outside festival season the valley walks and farmhouse dinners are the real Bhutan."},{"slug":"phuket","name":"Phuket","region":"South-East Asia","lat":7.885,"lon":98.389,"country":"Thailand","tagline":"Andaman beaches, limestone bays and barefoot luxury.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"6h","small":"1 stop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"November to March is dry, calm and radiant; the May-October monsoon brings rain and rough seas, though October's Vegetarian Festival is a spectacle worth the weather.","lede":"Phuket splits sharply between the built-up west-coast beaches and the quieter north and east, and where you stay decides your entire trip, so choose carefully. Skip Patong unless nightlife is the point; the discreet resorts sit around Mai Khao, Cape Panwa and the headlands. Come November to April for the calm sea, and give Phuket Old Town a proper afternoon for its Sino-Portuguese streets and food."},{"slug":"porto","name":"Porto","region":"Southern Europe","lat":41.15,"lon":-8.61,"country":"Portugal","tagline":"Granite, port wine and the river Douro's working banks.","facts":[{"label":"Best months","value":"Mar–Oct","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"13h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","peak","peak","peak","peak","shoulder","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Jul, Aug, Sep and Oct","whenBlurb":"Late spring and early autumn are warm and dry, with São João's midsummer madness on June 23rd; winters are wet and summers busy.","lede":"Porto is smaller and moodier than Lisbon, and better for it: the pleasure here is the river, the granite streets and the port lodges across the water in Gaia. Do one serious cellar visit and a tasting rather than three, walk the Ribeira at golden hour, and don't over-schedule; the city is compact enough to be enjoyed by drifting. The Douro valley is the reward for an extra day or two."},{"slug":"prague","name":"Prague","region":"Alpine & Central Europe","lat":50.087,"lon":14.421,"country":"Czechia","tagline":"City of a hundred spires above the winding Vltava","facts":[{"label":"Best months","value":"Apr–Aug","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"10.5h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","avoid","avoid"],"bestMonths":"Apr, May, Jun, Jul and Aug","whenBlurb":"Late spring and early autumn are mild and golden; December glows with Christmas markets. Avoid the packed midsummer heat and grey deep winter.","lede":"Prague is a walking city that punishes you for sleeping in, cross the Charles Bridge at dawn and you get it almost to yourself, by ten it's shoulder to shoulder. Give the castle a full morning and go beyond the courtyards into the smaller palaces. Skip the Old Town Square restaurants and eat in Vinohrady or Karlín where locals actually go."},{"slug":"queenstown","name":"Queenstown","region":"Oceania","lat":-45.032,"lon":168.661,"country":"New Zealand","tagline":"Alpine adventure capital on a glacial mountain lake.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"18h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~25d"}],"months":["peak","peak","peak","shoulder","shoulder","shoulder","shoulder","shoulder","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Sep, Oct, Nov and Dec","whenBlurb":"December to March delivers warm, long-lit days for the lake and hikes; June to August is ski season with the Winter Festival, and April brings Arrowtown's gold - there is no truly bad time.","lede":"Queenstown is an adrenaline town that quietly does luxury very well, the trick is to balance one big adventure day against slower time on the lake and in the wine country next door. Base in or near the centre for the first night, then consider decamping to the quieter side of the lake. Central Otago's wineries are half the reason to come and most people underrate them; don't."},{"slug":"ranthambore","name":"Ranthambore","region":"India","lat":26.019,"lon":76.456,"country":"India","tagline":"Tiger country where ruins meet wild jungle.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"2h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","avoid","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"The park runs October to June; cool October-March is the comfortable window, but the hot pre-monsoon months of April to June bring tigers to the waterholes for the best sightings; the core closes July to September.","lede":"Ranthambore is about the tiger, and that means patience and repeat drives, not a single game run squeezed onto a Golden Triangle day; give it at least three or four safaris across zones. Book the core zones and a good naturalist well ahead, and be clear-eyed that sightings are never guaranteed. The ruined fort and lakes inside the park are worth the trip even on a quiet-tiger day."},{"slug":"reykjavik","name":"Reykjavik","region":"Northern Europe","lat":64.146,"lon":-21.942,"country":"Iceland","tagline":"A small northern capital between volcano, ocean and aurora.","facts":[{"label":"Best months","value":"Aug–Sep","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"15h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~45d"}],"months":["shoulder","shoulder","avoid","avoid","avoid","shoulder","shoulder","peak","peak","avoid","shoulder","shoulder"],"bestMonths":"Aug and Sep","whenBlurb":"June to August brings the midnight sun and open roads; September to April, dark skies for the northern lights. Choose your light and dress for weather.","lede":"Reykjavik is really a warm, walkable base camp, you come for what's a short drive out, not for the city itself, though its restaurants and pools are genuinely good. Skip the Blue Lagoon near the airport for the quieter Sky Lagoon or a rural geothermal pool, and treat the town's public baths as the real local ritual. For the northern lights, base here in winter but be willing to chase clear skies with a private guide rather than trust a coach tour."},{"slug":"rio-de-janeiro","name":"Rio de Janeiro","region":"South America","lat":-22.911,"lon":-43.209,"country":"Brazil","tagline":"Mountains, beaches and samba meeting along a dazzling bay.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"24h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~10d"}],"months":["peak","peak","peak","shoulder","shoulder","shoulder","shoulder","shoulder","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Sep, Oct, Nov and Dec","whenBlurb":"December to March is warm and euphoric, crowned by Carnival and Reveillon; the heat and crowds peak then, so book far ahead or come in the milder shoulders.","lede":"Rio is best understood from its geography, the city is a negotiation between mountain, forest and beach, and the good days are spent moving between them. Base in the south zone, learn one beach stretch well rather than sampling all of them, and go up for the views early or late, never at midday. The favela-tour circuit is worth skipping; hire a good local guide instead and let them shape your days."},{"slug":"rishikesh","name":"Rishikesh","region":"India","lat":30.109,"lon":78.292,"country":"India","tagline":"Yoga capital of the world on the upper Ganges.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"1h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","peak","shoulder","shoulder","shoulder","avoid","avoid","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Apr, Oct, Nov and Dec","whenBlurb":"Spring and autumn bring warm days, cool nights and the year's great yoga gathering; skip peak-summer heat, and note July-August's monsoon closes river rafting.","lede":"Rishikesh has two faces, the spiritual-yoga town and the adventure-rafting town, and the trick is knowing which you came for and staying on the right bank. For calm, take the quieter upstream side and a serious retreat rather than the backpacker strip near the bridges. Come in the cooler months when the Ganga runs clear and the heat is off; skip the monsoon, when rafting closes."},{"slug":"rome","name":"Rome","region":"Southern Europe","lat":41.893,"lon":12.483,"country":"Italy","tagline":"The Eternal City, layered in empire, faith and dolce vita.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"9h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","shoulder","avoid","avoid","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Oct and Nov","whenBlurb":"Come in spring or early autumn for warm light and open piazzas; skip the searing, packed heat of July-August, when much of the city empties.","lede":"Rome rewards early mornings and long dinners; the Vatican and the Colosseum are yours only before nine or after five, so book the first slot and lunch late like a Roman. Don't try to see it all, stand in one great space, a piazza, a single church, and let it work rather than sprinting between checklists. Skip the restaurants ringing the monuments entirely; walk ten minutes into Trastevere or Monti and eat where the tables are Roman."},{"slug":"salzburg","name":"Salzburg","region":"Alpine & Central Europe","lat":47.798,"lon":13.046,"country":"Austria","tagline":"Baroque city of Mozart between fortress and alpine foothills","facts":[{"label":"Best months","value":"Apr–Sep","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"11h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","shoulder","shoulder","peak","peak","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"Apr, May, Jun, Jul, Aug and Sep","whenBlurb":"Summer belongs to the Salzburg Festival in July and August; December's Advent markets are pure enchantment and January brings Mozart Week, avoid only the grey, quiet late winter.","lede":"Salzburg is small and easily walked, so give it a couple of unhurried days rather than a rushed one, the Altstadt is the attraction, best seen early or late when the tour groups thin. It lives and breathes music; if you can align with the summer Festival or Mozart Week in January, do, because that's when the city is fully itself. Skip the Sound of Music bus tours unless that's genuinely your thing, and instead take the funicular up to the fortress for the view and a slow lunch."},{"slug":"san-francisco","name":"San Francisco","region":"North America","lat":37.81,"lon":-122.41,"country":"USA","tagline":"Fog-wreathed hills, the Bay and bracing reinvention.","facts":[{"label":"Best months","value":"Mar–Oct","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"16h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~180d"}],"months":["shoulder","shoulder","peak","peak","peak","peak","peak","peak","peak","peak","shoulder","shoulder"],"bestMonths":"Mar, Apr, May, Jun, Jul, Aug, Sep and Oct","whenBlurb":"Come September-October for the warmest, clearest days and Fleet Week's airshow; summer is famously cool and foggy, and Napa's harvest crush runs August through October an hour north.","lede":"San Francisco is a city of microclimates and neighbourhoods, not landmarks, cross the Golden Gate early before the fog rolls in, and read the summer for what it is (cold and grey; September and October are the warm months). Skip Fisherman's Wharf and give the time to the Ferry Building, the Mission's food, and a day up in the wine country. The best views are from the Marin headlands looking back."},{"slug":"santorini","name":"Santorini","region":"Southern Europe","lat":36.407,"lon":25.457,"country":"Greece","tagline":"Whitewashed caldera villages above a sunken volcano.","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"13h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"May-June and September are the honest sweet spots, warm and calmer around the caldera; July-August is beautiful but crowded, and much of the island shuts through winter.","lede":"Santorini is spectacular and oversold at once, the caldera is real, the Oia sunset scrum is not worth it. Watch the sun go down from a private terrace or a boat instead, and give the mornings to the quieter southern villages like Pyrgos and Megalochori. Come in May or late September; July and August are hot, packed and unkind to the cliff paths."},{"slug":"seoul","name":"Seoul","region":"East Asia","lat":37.567,"lon":126.978,"country":"South Korea","tagline":"Palaces and hypermodernity, served at every hour.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"7h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~7d"}],"months":["avoid","avoid","peak","peak","peak","shoulder","avoid","avoid","peak","peak","peak","avoid"],"bestMonths":"Mar, Apr, May, Sep, Oct and Nov","whenBlurb":"Spring blossom (Apr) and autumn colour (Oct–Nov) are the peaks; skip the humid, wet July–August and the deep winter cold.","lede":"Seoul is a night city and a mountain city at once, the palaces by day, the food alleys and hills after dark. Do Gyeongbokgung early and catch the guard-changing, but the quieter pleasure is Changdeokgung's Secret Garden on a timed ticket. Everyone crowds Bukchon for photos; go on a weekday morning and remember people actually live there."},{"slug":"shanghai","name":"Shanghai","region":"East Asia","lat":31.232,"lon":121.469,"country":"China","tagline":"Art-deco riverfront facing a skyline of tomorrow.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"6.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~5d"}],"months":["avoid","avoid","peak","peak","peak","shoulder","shoulder","avoid","peak","peak","peak","avoid"],"bestMonths":"Mar, Apr, May, Sep, Oct and Nov","whenBlurb":"Come in spring for cherry blossom and Fashion Week, or October-November for clear skies and the art season; skip the muggy July-August heat and damp winter chill.","lede":"Shanghai's pleasure is the contrast between the two riverbanks: the 1920s Bund and French Concession on one side, the science-fiction Pudong skyline on the other, and the trick is to sleep on the old side and admire the new one from across the water. Walk the plane-tree lanes of the former French Concession in the afternoon rather than queuing for observation decks, and save the Bund for a night when it is lit. The city is very easy to over-programme; leave time to simply wander the lane houses."},{"slug":"shimla","name":"Shimla","region":"India","lat":31.104,"lon":77.171,"country":"India","tagline":"Colonial hill-station grandeur amid Himalayan cedar forests.","facts":[{"label":"Best months","value":"May–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"1.5h","small":"1 stop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["shoulder","shoulder","shoulder","shoulder","peak","peak","shoulder","avoid","avoid","shoulder","peak","peak"],"bestMonths":"May, Jun, Nov and Dec","whenBlurb":"Spring and early summer are pleasant and green; late December brings snow and the Winter Carnival. Avoid the July-to-September monsoon and its landslides.","lede":"Shimla is at its best out of season and out of the town centre; the Mall Road crush is precisely what to avoid, so base yourself a little outside and use the town for its colonial architecture and walks. The toy-train up from Kalka is a genuine pleasure and worth building the trip around. Come in spring or autumn; peak summer and the snow-season weekends bring Delhi's traffic with them."},{"slug":"siem-reap","name":"Siem Reap","region":"South-East Asia","lat":13.362,"lon":103.859,"country":"Cambodia","tagline":"Gateway to Angkor's temples and Khmer artistry.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"7h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~3d"}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"November to February brings dry, temperate mornings ideal for Angkor at dawn and the river's boat races; time the March or September equinox for sunrise aligned to the central tower, and avoid the March-May heat and summer monsoon.","lede":"Siem Reap is Angkor, and Angkor rewards patience, a three-day temple pass and a good private guide beat a rushed single day every time. Everyone piles into Angkor Wat for sunrise; the light is often better and the crowds thinner at Ta Prohm mid-morning or at Bayon's faces late afternoon. Base yourself well and treat the town itself as somewhere to rest, not sightsee."},{"slug":"singapore-city","name":"Singapore","region":"South-East Asia","lat":1.357,"lon":103.819,"country":"Singapore","tagline":"A garden city of gleaming towers and hawker soul.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"4.5h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~4d"}],"months":["peak","peak","shoulder","shoulder","shoulder","shoulder","shoulder","peak","peak","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Aug, Sep, Nov and Dec","whenBlurb":"Come February to April for the driest, brightest days; time it to Art Week in January or the Grand Prix in autumn, and expect frequent showers year-round.","lede":"Singapore is best read as a food city with a skyline, not the other way round, spend as much time in a Tiong Bahru coffee shop as at Marina Bay. The Gardens by the Bay light show is worth it, but go into the Cloud Forest dome at opening before the tour groups. Everyone rushes the Sands SkyPark; the better view is a drink at a bar across the water looking at it."},{"slug":"srinagar","name":"Srinagar","region":"India","lat":34.075,"lon":74.82,"country":"India","tagline":"Mughal gardens, houseboats and the still mirror of Dal Lake.","facts":[{"label":"Best months","value":"May–Aug","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","shoulder","shoulder","avoid","avoid"],"bestMonths":"May, Jun, Jul and Aug","whenBlurb":"Come for tulips and gardens in April, gardens and Dal Lake through summer, and chinar colour in autumn; winter is cold, snowbound and hushed.","lede":"Srinagar is a lake-and-garden city best taken gently, and the classic way in is a night or two on a well-kept houseboat on Dal or, better, the quieter Nigeen Lake. Do the shikara at dawn for the floating vegetable market and the Mughal gardens in the late afternoon light. Check the situation before you commit, and lean on a good local operator; conditions can change, and local knowledge matters here."},{"slug":"st-moritz","name":"St. Moritz","region":"Alpine & Central Europe","lat":46.498,"lon":9.839,"country":"Switzerland","tagline":"Engadine glamour where alpine sport meets old-world luxury","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"9.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["peak","peak","peak","shoulder","avoid","avoid","avoid","shoulder","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Sep, Oct, Nov and Dec","whenBlurb":"December to March for snow and the frozen-lake season of White Turf and Snow Polo; July and August for high-alpine hiking. Avoid the muddy shoulder weeks when much closes.","lede":"St. Moritz is at its best in winter, when the frozen lake becomes the whole point, this is where high-altitude sport meets old-money leisure, and you should lean into that rather than treat it as just a ski resort. Base yourself for the events and long lunches, not the piste-bashing; the skiing at neighbouring Corviglia and Corvatsch is good but the town's real currency is the après and the people-watching. Come in late January or February; a summer visit is quieter and lovelier for walking but misses the theatre."},{"slug":"sydney","name":"Sydney","region":"Oceania","lat":-33.87,"lon":151.208,"country":"Australia","tagline":"Harbour city of sails, surf and golden light.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"5","small":"days"},{"label":"From India","value":"12.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~25d"}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Nov and Dec","whenBlurb":"Warm and bright in the Australian spring (Oct–Dec) and autumn (Mar–Apr); Vivid lights up June, but the summer holidays are hot and busy.","lede":"Sydney is a harbour town before it is a city, so organise everything around the water, the ferries are the best value in Australian travel and the finest way to see the place. Do the Opera House and the bridge, then get out to the eastern beaches and the northern coves where locals actually spend their weekends. Skip Darling Harbour; give that time to a Manly ferry and a coastal walk instead."},{"slug":"taipei","name":"Taipei","region":"East Asia","lat":25.038,"lon":121.564,"country":"Taiwan","tagline":"Night-market warmth beneath a soaring green tower.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"7h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~3d"}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","shoulder","peak","peak","peak"],"bestMonths":"Jan, Feb, Oct, Nov and Dec","whenBlurb":"Come in spring or autumn for mild, dry days and blossom or lantern light. Avoid the humid heat and typhoons of June to September.","lede":"Taipei is warmer and more relaxed than its bigger East Asian neighbours, and the right way to take it is slowly, with the night markets, the hot springs, and the tea hills all in easy reach. Skip the obligatory tower-observation-deck routine and instead spend an afternoon in the mountain teahouses of Maokong, then come down for a proper night-market dinner. The food is the reason to come, and it is best eaten standing up, one stall at a time."},{"slug":"tokyo","name":"Tokyo","region":"East Asia","lat":35.677,"lon":139.764,"country":"Japan","tagline":"Neon precision and quiet ritual in endless measure.","facts":[{"label":"Best months","value":"Mar–Nov","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"8.1h","small":"nonstop"},{"label":"Visa","value":"E-visa","small":"~7d"}],"months":["shoulder","shoulder","peak","peak","peak","shoulder","avoid","avoid","peak","peak","peak","shoulder"],"bestMonths":"Mar, Apr, May, Sep, Oct and Nov","whenBlurb":"Late March to early April for cherry blossom, and late October–November for autumn colour, are the two windows worth planning a year around. Skip Golden Week (late Apr–early May) and the August heat.","lede":"Tokyo rewards precision and punishes the scattershot, pick two or three neighbourhoods and go deep rather than sprinting across the map. Book the difficult tables the moment you have dates; the best counters seat eight and vanish months out. And spend at least one evening entirely off the tourist grid, in a six-seat basement bar in Golden Gai or a yokocho under the tracks, where no one is trying to sell you Tokyo."},{"slug":"toronto","name":"Toronto","region":"North America","lat":43.653,"lon":-79.384,"country":"Canada","tagline":"Canada's polyglot metropolis on the Lake Ontario shore.","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"15h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~60d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"Late spring and autumn are the sweet spot, with TIFF in September and fall foliage close by; Caribana lights up summer, but winters are severely cold.","lede":"Toronto is best read through its neighbourhoods and its food, which is genuinely one of the most diverse in the world, eat your way across Kensington, Little Italy and the east-end pockets rather than chasing the CN Tower. It's a walkable, low-drama city that rewards a slower pace and a good weather window; summer and early autumn are when it comes alive. Use it as a base for the islands and, with a full day to spare, Niagara."},{"slug":"udaipur","name":"Udaipur","region":"India","lat":24.579,"lon":73.686,"country":"India","tagline":"The lake city of marble palaces and Aravalli hills.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"1.3h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","avoid","avoid","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Oct, Nov and Dec","whenBlurb":"Come October to March for cool, lake-full days; time it to the World Music Festival in February or Mewar Festival in spring, and avoid the searing April-to-June heat.","lede":"Time everything around water and light, a sunset boat on Lake Pichola, breakfast on a terrace facing the City Palace, an evening when the palaces are floodlit and reflected. Two full days is enough for the city itself; use a third for a slow drive to Kumbhalgarh fort or the Ranakpur Jain temples. Avoid the monsoon-fed crowds around Diwali if you want the ghats to yourself, and always ask for a lake-facing room, the difference is the entire visit."},{"slug":"vancouver","name":"Vancouver","region":"North America","lat":49.261,"lon":-123.114,"country":"Canada","tagline":"Mountains, sea and rainforest framing a glass city.","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"15.5h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~60d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"Come June to September for dry, glorious days on ocean and mountain; time spring for cherry blossom and whale season, and expect grey rain the rest of the year.","lede":"Vancouver rewards the traveller who treats the city as a base rather than the destination, the mountains, the ocean and the islands are where it comes alive. Give downtown a night or two, then point yourself at Stanley Park, the North Shore and the water. Skip the aquarium-and-Gastown-clock circuit; spend that time on Granville Island early, before the tour groups."},{"slug":"varanasi","name":"Varanasi","region":"India","lat":25.336,"lon":83.008,"country":"India","tagline":"India's eternal city of light upon the Ganges.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"3","small":"days"},{"label":"From India","value":"1.5h","small":"nonstop"},{"label":"Visa","value":"Visa-free","small":null}],"months":["peak","peak","peak","shoulder","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak"],"bestMonths":"Jan, Feb, Mar, Nov and Dec","whenBlurb":"October to March gives cool, clear days along the ghats, with November's Dev Deepawali the most spectacular night of all; avoid the punishing summer and the monsoon floods.","lede":"Varanasi is India at its most intense and sacred, and it asks you to slow down, take a boat on the Ganga at dawn as the ghats wake, and again at dusk for the Ganga Aarti at Dashashwamedh. Watch the aarti from a boat on the water rather than the packed steps. Walk the old lanes with a guide; getting lost here is not romantic, it's disorienting. Come with respect, not a camera aimed at the cremation ghats."},{"slug":"venice","name":"Venice","region":"Southern Europe","lat":45.437,"lon":12.335,"country":"Italy","tagline":"A city of water, palaces and impossible beauty.","facts":[{"label":"Best months","value":"Apr–Nov","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"11.5h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["shoulder","avoid","shoulder","peak","peak","peak","shoulder","shoulder","avoid","peak","peak","shoulder"],"bestMonths":"Apr, May, Jun, Oct and Nov","whenBlurb":"Come late spring or September for luminous light and the season in full swing; sidestep the August crush and the autumn acqua alta floods.","lede":"Stay two nights minimum so you can have the city at dawn and after the day-trippers leave on the last trains, that empty, echoing Venice is the only one worth the trouble. Cross the lagoon to Torcello or Burano for a long lunch rather than grinding through San Marco at midday. And take a water taxi from the airport at least once; arriving by boat is the whole point."},{"slug":"vienna","name":"Vienna","region":"Alpine & Central Europe","lat":48.208,"lon":16.373,"country":"Austria","tagline":"Imperial palaces, coffee houses and music in the grand manner","facts":[{"label":"Best months","value":"Apr–Aug","small":null},{"label":"Ideal length","value":"4","small":"days"},{"label":"From India","value":"8.75h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","shoulder","shoulder","avoid"],"bestMonths":"Apr, May, Jun, Jul and Aug","whenBlurb":"Late spring and early autumn are mildest; December brings Christmas markets and January-February the glittering ball season, though winter beyond that is grey and cold.","lede":"Vienna rewards a slower pace than most visitors give it, the pleasure is in the coffee houses, the concert halls and the museums, not in racing between sights. Prioritise a proper opera or Musikverein evening and an afternoon that does nothing but a Kaffeehaus and a walk; skip the tourist-trap Mozart concerts sold on the Kärntner Straße. Time a visit for the ball season in winter or the arts festival in early summer, and don't overlook the outer districts for food and wine."},{"slug":"zanzibar","name":"Zanzibar","region":"Africa","lat":-6.1,"lon":39.321,"country":"Tanzania","tagline":"Swahili spice island of dhows, coral lanes and turquoise sea.","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"7","small":"days"},{"label":"From India","value":"9.5h","small":"1 stop"},{"label":"Visa","value":"E-visa","small":"~7d"}],"months":["peak","peak","shoulder","shoulder","avoid","avoid","avoid","shoulder","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Sep, Oct, Nov and Dec","whenBlurb":"The long dry season from June to October is ideal, with February bringing Sauti za Busara and its own dry spell; skip the long rains of March to May.","lede":"Stone Town rewards a day or two of unhurried wandering, then the north and east coasts are where you settle, Nungwi and Matemwe for reliable swimming, the southeast for quiet. Skip the packaged spice tours and the overbuilt Kendwa strip; hire a private guide who actually knows the farms and the alleys. Tides here are dramatic, so pick your beach for whether you want to swim at all hours or don't mind walking out at low water."},{"slug":"zermatt","name":"Zermatt","region":"Alpine & Central Europe","lat":46.021,"lon":7.749,"country":"Switzerland","tagline":"Car-free alpine village beneath the unmistakable Matterhorn","facts":[{"label":"Best months","value":"Jan–Dec","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"13h","small":"1 stop"},{"label":"Visa","value":"Visa needed","small":"~15d"}],"months":["peak","peak","peak","shoulder","shoulder","avoid","avoid","shoulder","peak","peak","peak","peak"],"bestMonths":"Jan, Feb, Mar, Sep, Oct, Nov and Dec","whenBlurb":"January to March for snow-sure skiing under the Matterhorn, July to August for high-alpine hiking. Shoulder weeks bring quiet and some lift closures.","lede":"Zermatt is car-free and all about the Matterhorn, so the game is catching the mountain in clear light, the peak often clouds by late morning, so be up early. Take the Gornergrat railway at dawn for the classic view, and ride to the highest station in Europe at Matterhorn Glacier Paradise. The village itself is charming but the reason to come is above 3,000 metres."},{"slug":"zurich","name":"Zurich","region":"Alpine & Central Europe","lat":47.374,"lon":8.541,"country":"Switzerland","tagline":"Banking grandeur, lakeside calm and Alpine air in one","facts":[{"label":"Best months","value":"May–Sep","small":null},{"label":"Ideal length","value":"6","small":"days"},{"label":"From India","value":"9h","small":"nonstop"},{"label":"Visa","value":"Visa needed","small":"~14d"}],"months":["avoid","avoid","shoulder","shoulder","peak","peak","peak","peak","peak","shoulder","avoid","avoid"],"bestMonths":"May, Jun, Jul, Aug and Sep","whenBlurb":"June to September for lake days, alpine trails and the pre-Art-Basel art weekend, or December for ski access and Christmas markets; the shoulder months of spring are quiet and mild.","lede":"Zurich is easy to underrate as merely tidy and rich; give it a day or two and the lake, the swimmable river and a genuinely serious art scene reveal themselves. Prioritise the Kunsthaus and a slow afternoon on the water over ticking off the Bahnhofstrasse, and in summer swim where the locals do at the badis along the Limmat. It is compact, punctual and expensive, so plan fewer things and do them well."}]

export const MONTHS: MonthGuide[] = [{"no":1,"code":"Jan","name":"January","heading":{"text":"Go in January.","accent":"January"},"lede":"The deepest part of the Northern winter. The right time for sun, for the Southern summer, and for the desert at its kindest.","statement":"Chase the sun, or the season.","note":"The festive rush is over, and fares ease after the first week. A quiet, generous start to the travel year.","intro":"North India is at its coldest, and that is the point. The Indian Ocean is glassy and dry, the Southern hemisphere is deep in summer, the Gulf and the deserts warm by day, cool by night. Travel after the first week, once the New-Year peak lets go of seats and rates, and it becomes one of the best-value months of the year.","where":[{"heading":"The Maldives & Seychelles","text":"The dry north-east monsoon brings calm, clear water and reliable sun, the overwater villa at its best. It is high season, so the finest resorts should be held well in advance. The reward is the ocean at its most flawless."},{"heading":"South Africa & the Cape","text":"High summer in the Southern hemisphere: Cape Town's long beach days, the Winelands in full leaf, warm and dry along the coast. Game viewing in the bushveld is greener and lusher now than in the dry winter, a different, blooming safari."},{"heading":"New Zealand & Australia","text":"The Antipodean summer at its height, the South Island's lakes and alps, Sydney and the coast. Long daylight and warm weather make January ideal. It also coincides with local school holidays, so the marquee lodges fill early."},{"heading":"The UAE, Oman & the desert","text":"The Gulf and Arabia are at their most comfortable, warm sun, cool evenings, the dunes pleasant rather than punishing. Short flights from India make this the easy long-weekend winter escape, with the desert camps at their best."}],"avoid":[{"heading":null,"text":"Northern Europe and the UK are short on daylight, cold and often grey, lovely for Christmas markets in December, less so by mid-January unless you are there for the snow."},{"heading":null,"text":"The Mediterranean, Greece, Italy, Türkiye, is out of season: cool, wet, and much of the island and coastal life shuttered. Save it for the shoulder."},{"heading":null,"text":"The far north of South-East Asia can be cooler and hazier. The headline beaches are fine, but this is not the month for the hill country."}],"indianAngle":[{"heading":null,"text":"Republic Day late in the month often falls near a weekend, a natural window for a short escape to the Gulf, Sri Lanka or the Maldives."},{"heading":null,"text":"The first week still carries New-Year peak pricing. Travel from the second week, and both fares and rates ease noticeably."},{"heading":null,"text":"School terms are mid-session, so January suits couples and unhurried travellers more than family groups, quieter resorts, easier tables, calmer flights."}],"flightsVisas":[{"heading":null,"text":"Book flights early. A January departure sits inside the festive and New-Year peak, so fares are best secured well ahead, ideally by September or October. Premium-cabin award space to the Maldives, Cape Town and the Antipodes is thin in this window. Your advisor watches it for you."},{"heading":null,"text":"Visa lead time. South Africa and Australia require visas for Indian passport holders, and peak-season processing runs longer, so your advisor starts early, typically a couple of months out, to keep your dates safe. The Maldives is visa-on-arrival and the UAE e-visa is quick, but Australia and South Africa are the ones to begin in good time."},{"heading":null,"text":"The principle. Visa timelines and requirements change. We confirm the current position for your passport and route before you commit, and file early enough that the paperwork never decides your dates."}],"pull":"Home is wrapped up against the cold. You are somewhere the sun never left."},{"no":2,"code":"Feb","name":"February","heading":{"text":"Go in February.","accent":"February"},"lede":"Home is still in winter. The tropics and the desert are at their clearest. Few finer months to be on the water, or among the dunes.","statement":"Warm escapes, at their best.","note":"The New-Year peak has cleared and fares have settled. The steady heart of the dry season.","intro":"North India is still cold, so a warm escape wins. The Indian Ocean and South-East Asia sit deep in dry season, calm seas, dependable sun. The Arabian and North-African deserts are warm by day, cool by night. With the January rush behind us, the window turns generous: settled weather, easier fares, the islands at their best.","where":[{"heading":"Sri Lanka","text":"The west and south coasts are in their dry season, which makes February right for both the beaches and the cultural triangle. Clear days for Galle and the southern bays, comfortable touring inland. A short flight from India keeps it close, and the conditions are about as reliable as the island offers."},{"heading":"Thailand & the Andaman","text":"Peak dry season across the south: calm seas, gentle swell, the islands at their most inviting. The sun is dependable now, the diving and island-hopping at their best. It is a popular window, so the finest villas and resorts reward booking ahead."},{"heading":"Egypt & the Nile","text":"The desert is cool and clear, which makes February a comfortable month for Luxor and Aswan and the pyramids before the heat builds again. Days are pleasant for the temples and the Nile, evenings crisp. It is a fine window to see the great sites without the punishing sun of later in the year."},{"heading":"The UAE & Oman","text":"The Gulf and Arabia are still in the sweet spot: warm days, cool nights, the dunes and the coast at their kindest. Easy long-weekend distance from India makes this the natural short winter escape, with the desert camps and the beaches both at their best."}],"avoid":[{"heading":null,"text":"Northern Europe and the UK stay cold and short on daylight. Handsome in their way, but this isn't the month for cities best seen in the long light of summer, unless you're there for the snow."},{"heading":null,"text":"The Mediterranean is still out of season: cool, often wet, and much of the island and coastal life closed until spring. It is worth the wait for the shoulder months."},{"heading":null,"text":"Bali and parts of South-East Asia can be in a wetter spell now, with humidity and afternoon rain more likely. Fine in stretches, but less dependable than the Andaman or Sri Lanka this month."}],"indianAngle":[{"heading":null,"text":"School terms are mid-session, so February leans toward couples and unhurried travellers: calmer resorts, easier tables, gentler flights than the family-heavy peaks."},{"heading":null,"text":"With the January peak cleared, fares ease and good value returns. A welcome stretch before the spring rush begins to lift prices again."},{"heading":null,"text":"The occasional long weekend can open a short escape to the Gulf, Sri Lanka or the Andaman. Worth holding dates early when one lines up."}],"flightsVisas":[{"heading":null,"text":"Book the short-hauls ahead. The popular near-India routes, Sri Lanka, the Andaman, the Gulf, fill quickly when a long weekend lines up, so seats and good fares are best held well in advance. Your advisor watches the routes that matter to you and secures the window before it tightens."},{"heading":null,"text":"Visa lead time. Sri Lanka's ETA, Thailand's visa-on-arrival, and the UAE e-visa are all quick for Indian passport holders. Egypt is the one to begin early. Your advisor starts the paperwork in good time, typically a few weeks out, so the filing never decides your dates."},{"heading":null,"text":"The principle. Visa timelines and requirements change. We confirm the current position for your passport and route before you commit, and file early enough that everything is settled and confirmed before you travel."}],"pull":"Home stays wrapped against the cold. You are somewhere the sky is wide and the water is still."},{"no":3,"code":"Mar","name":"March","heading":{"text":"Go in March.","accent":"March"},"lede":"Spring opens. Japan's first blossom, Jordan and Oman at their finest, Europe quietly waking. The gentlest weeks of the year, before the crowds.","statement":"The gentlest window of the year.","note":"Winter loosens its grip and the year's loveliest weeks open. The great destinations begin to wake, before the crowds arrive.","intro":"Japan edges into its first cherry blossom. Jordan and Oman enjoy their finest weeks before the summer heat. Spain and Portugal stir in early warmth, and the desert holds its last cool days. North India is pleasant before the build to summer. A natural moment to travel, and a quiet advantage too, spring's best places are still calm and well-priced.","where":[{"heading":"Japan","text":"The first cherry blossom typically arrives around late March, though the bloom shifts year to year and is impossible to pin to a date in advance. The air is mild and the light is kind, with Tokyo and Kyoto at their loveliest. Because the timing can't be known, the right itinerary follows the blossom rather than betting on a single week."},{"heading":"Jordan & Oman","text":"This is arguably their finest window, spring warmth before the summer heat sets in. Petra and Wadi Rum are comfortable to explore by day, and Oman's coast and mountains are at their most welcoming. Clear skies and gentle temperatures make for long, unhurried days."},{"heading":"Spain & Portugal","text":"Early spring rewards those who go now: mild, walkable cities and a fraction of the summer crowds. Seville and Lisbon are at their easy best, the terraces filling but never full. Prices are kinder, too, before the season turns."},{"heading":"Egypt & the desert's last cool","text":"Egypt is comfortable before the heat builds, the temples and the Nile pleasant rather than punishing. The UAE and Oman are in the tail end of their pleasant season, the dunes still kind by day. A short flight from India makes this an easy late-winter escape."}],"avoid":[{"heading":null,"text":"The Maldives and the wider Indian Ocean are easing toward their changeover into the wetter months. Early March is still lovely, but conditions grow less certain as the weeks pass. Go early if you go."},{"heading":null,"text":"High-altitude alpine skiing is in its tail end, and snow quality becomes variable. The best of the season is behind you by now."},{"heading":null,"text":"The hotter destinations, parts of South-East Asia, the deep desert, are starting to warm. A later spring trip there will be less forgiving than one taken now."}],"indianAngle":[{"heading":null,"text":"Holi usually falls somewhere this month, the exact date moves with the calendar, and can open a welcome long weekend for a short, well-timed escape."},{"heading":null,"text":"School exams and term-end mean families travel less just now, so March suits couples and unhurried travellers, quieter resorts, easier tables, calmer flights."},{"heading":null,"text":"If a June trip to Europe is on your mind, the Schengen file opens now. March is the month to begin, so the paperwork is never the thing that decides your dates."}],"flightsVisas":[{"heading":null,"text":"Book flights early. Japan's cherry-blossom season books out well in advance, flights and the best stays should be secured months ahead, since demand far outstrips the rooms in Tokyo and Kyoto. Your advisor holds space the moment it opens, and watches award availability so you don't have to."},{"heading":null,"text":"Visa lead time. A summer trip to Europe means the Schengen file should be filed from March, while appointment slots are still calm. Japan and Jordan visas reward an early start too. Your advisor begins in good time, so your dates never come under pressure."},{"heading":null,"text":"The principle. Visa timelines and requirements change. We confirm the current position for your passport and route before you commit, and file early enough that the paperwork never decides your dates."}],"pull":"The first warm light of the year, and a terrace just waking to meet it."},{"no":4,"code":"Apr","name":"April","heading":{"text":"Go in April.","accent":"April"},"lede":"The Mediterranean is warm and quiet, the desert is in its last clear weeks, and Europe is at its gentlest before the summer fills it.","statement":"The quiet before the peak.","note":"Spring has reached the Mediterranean. The crowds haven't. April is the window, just ahead of the rush.","intro":"As home begins to heat up, cooler Europe starts to call, and April catches it at the right moment. The southern Mediterranean is warm and dry but still pre-season. The desert has its last comfortable weeks before summer. Rates and crowds are a fraction of what May and June will bring. Full beauty, half the company.","where":[{"heading":"Spain & Portugal","text":"Warm, dry and quiet. Andalusia comes into bloom, and Lisbon and Porto are at their most walkable before the summer fills them. The light is long and soft, the terraces are open, and the great cities are yours rather than the tour groups'."},{"heading":"Türkiye","text":"Spring suits this country. Istanbul is mild and in blossom, the Aegean coast is warming, and Cappadocia is at its gentlest before the heat. Prices stay kind in April, and the landscapes, green hills, tulips, clear morning skies, are at a brief, lovely peak."},{"heading":"Italy","text":"The great shoulder month. Rome and Tuscany are warm and quiet, and the Amalfi coast begins to open, hotels and restaurants waking from winter without the August crush. You get the long Italian evening and the famous tables, and none of the queues that come later."},{"heading":"Jordan & Oman","text":"The desert has its final comfortable weeks. Petra and the wadis are pleasant by day, the dunes warm rather than searing. The window is closing as summer approaches, so April is among the last easy months to be here. After this, the heat takes over."}],"avoid":[{"heading":null,"text":"The Indian Ocean, the Maldives especially, is edging into its wetter, less reliable spell. The islands still charm, but the glassy, guaranteed-sun window is closing for the season."},{"heading":null,"text":"The Gulf and the deep desert begin to turn hot late in the month. Comfortable early on, fiercer by day as April runs out, so go early rather than late, if you go at all."},{"heading":null,"text":"Far-northern Europe and Scandinavia stay cool and variable. Spring arrives slowly up there, and the long, warm days are still some weeks off."}],"indianAngle":[{"heading":null,"text":"The school year is winding down, and the big May–June family break is just ahead. That makes April the quieter choice for couples and families who can move before the crowds do."},{"heading":null,"text":"If you're planning a summer Schengen trip, the application you filed in March should now be in process. April is the month to let the lead time work for you, not against you."},{"heading":null,"text":"The month tends to throw up a long weekend or two. Paired with a short Mediterranean or Gulf hop, they make an easy spring escape before peak fares set in."}],"flightsVisas":[{"heading":null,"text":"Book ahead. April is shoulder-season value, but the May–June peak sits just behind it, and demand for early-summer seats builds fast. Secure flights well in advance, and let your advisor watch premium-cabin availability rather than chase it late."},{"heading":null,"text":"Visa lead time. If June travel is in your sights, the Schengen application should already be filed. A March start keeps your dates safe through peak-season processing. Your advisor begins visas early, so the paperwork is moving long before you need to commit."},{"heading":null,"text":"The principle. Visa requirements and timelines shift. We confirm the current position for your passport and route before you book, and file early enough that the process never decides your dates for you."}],"pull":"Spring has reached the coast, and for now it is yours alone."},{"no":5,"code":"May","name":"May","heading":{"text":"Go in May.","accent":"May"},"lede":"The Mediterranean is warm and unhurried. The far north fills with light. Bali's dry season opens. The best window before summer fills up.","statement":"Catch the season at its best.","note":"The school break opens and home turns hot. Families look outward, and the cooler, sunnier corners of the world are at their kindest.","intro":"The Indian plains move into their fiercest heat, the cue to leave. The Mediterranean has warmed into early summer without the July crowds. The Nordic north begins its long, luminous days. Bali slips into its dry, dependable season. This is the family window, and the finest villas and connecting suites are claimed early. Plan in good time and May gives you sun, space, and a quieter map.","where":[{"heading":"Greece & the Greek islands","text":"The seas have warmed enough to swim and the light stretches late into the evening, yet the July and August crush is still weeks away. This is the shoulder season at its best. Santorini and the Cyclades are open and lively without being overrun, the tavernas easy, the water clear."},{"heading":"Italy & the Amalfi Coast","text":"Late spring eases into early summer along the coast. The lemon terraces are in bloom, the sea swimmable, the towns awake but not yet full. It is the right moment for the cliffside drive and the long lunch by the water, before high season arrives."},{"heading":"Iceland & the Nordics","text":"The days grow long and mild as the white-nights season begins, opening the highlands and the quieter roads. Reykjavík, the Norwegian fjords and Swedish Lapland are gentle and easy to reach now, with daylight that seems never to end. A wholly different escape from the heat at home."},{"heading":"Bali & Indonesia","text":"The dry season takes hold, bringing reliable sun, gentle humidity and some of the year's best surf. May is the quiet, golden stretch before the July peak. The rice terraces are green, the resorts unhurried, the island calm."}],"avoid":[{"heading":null,"text":"The Gulf and the Arabian desert have turned genuinely hot. The dunes and open-air evenings that delight in winter become punishing by May. Save Dubai and Oman for the cooler half of the year."},{"heading":null,"text":"India's own plains are at the peak of their heat, the reason to travel, not a place to linger. The hills hold up better; the lowlands are best left behind."},{"heading":null,"text":"Parts of South-East Asia begin sliding into their wet season around now. Afternoon storms are likely in places, so timing and region matter. Your advisor steers you to the side of the map still in fine weather."}],"indianAngle":[{"heading":null,"text":"This is the summer school break, when families travel in number. Europe and the long-haul favourites fill fast, and the best villas and connecting suites go to those who book first. The earlier the better."},{"heading":null,"text":"Demand peaks across the whole window, so premium cabins and marquee lodges are the first to go. Securing dates well ahead is the difference between the trip you want and the trip that's left."},{"heading":null,"text":"A May journey into Schengen Europe needed its visa file opened around February or March. For late planners that lead time has likely passed, so plan further ahead next year, and let your advisor set the clock running."}],"flightsVisas":[{"heading":null,"text":"Book flights early. Peak family demand means flights and premium cabins to Europe and Bali sell out well ahead of departure. The earlier you commit, the better the routing and the cabin. Award space in this window is especially thin, and your advisor watches it for you."},{"heading":null,"text":"Visa lead time. Schengen files for a May or June journey must be in well ahead of travel, as peak-season processing runs long. Your advisor starts early to keep your dates safe. Indonesia's visa-on-arrival or e-VOA is quick and straightforward. Iceland and the Nordics sit within Schengen, so the same early-file discipline applies."},{"heading":null,"text":"The principle. Visa timelines and requirements shift. We confirm the current position for your passport and route before you commit, and open each file early enough that the paperwork never decides your dates."}],"pull":"While home turns to its hottest, you are by a cooler sea, the evening stretching long."},{"no":6,"code":"Jun","name":"June","heading":{"text":"Go in June.","accent":"June"},"lede":"The summer break, and the monsoon arriving at home. The right time for the Alps in flower, the fjords, the long Northern light.","statement":"Follow the cool and the light.","note":"School lets out and the rains settle over home. The family month, and the case for going north is a simple one.","intro":"As the monsoon arrives across India, the half of the world above the Alps comes into its best fortnight. Switzerland turns green and the high passes open. Norway's fjords sit under a sky that barely darkens. France and Britain stretch into their longest, gentlest days. June belongs to those who go where the days are long and the air stays cool, and who plan furthest ahead, because everyone else is travelling too.","where":[{"heading":"Switzerland & the Alps","text":"Summer in the mountains at its most generous: green meadows, mirror lakes, the high walks open and the panoramic trains running their full routes. The weather is mild and dependable enough for unhurried days, which makes this the kindest stretch of the year for families. Long evenings leave room for the lake before dinner."},{"heading":"Scandinavia & the fjords","text":"Norway's fjords are at their most dramatic now, the cliffs deep green and the waterfalls full from the melt. This is the season of the white nights, when the light lingers almost to midnight in the far north and the days feel endless. Mild and bright, it suits cruising the coast and the slow, scenic rail."},{"heading":"France","text":"Paris is at its early-summer best, café terraces, the gardens in leaf, light that holds late into the evening. The Riviera warms without the deep-summer crush, and Provence begins to colour, though the lavender truly peaks a little later, around July. A country made for June's long, soft light."},{"heading":"The UK & Ireland","text":"Britain and Ireland are at their greenest, with the longest days of the year and the great gardens in full bloom. The countryside is gentle and the weather generally kind, made for slow drives and country houses. Pack for changeable skies all the same, a bright morning here can turn before lunch."}],"avoid":[{"heading":null,"text":"The Indian Ocean, the Maldives and its neighbours, drifts into its wetter, windier spell now. You may still catch fine days, but the reliably glassy water has moved on for the season."},{"heading":null,"text":"The Gulf and the deserts are in fierce heat by June, the daytime conditions making the dunes and the open city punishing rather than pleasant. Best left for the cooler months."},{"heading":null,"text":"The Mediterranean is entering its hotter, busier July run-up, Greece, Italy and the Spanish coast grow warm and crowded. Lovely, but not the quiet version. The shoulder months serve it better."}],"indianAngle":[{"heading":null,"text":"June is the height of the school summer holidays, the single highest-demand family window of the year for Europe and the long-haul north. Book furthest ahead of any month; the best lodges and suites are spoken for early."},{"heading":null,"text":"This is when Schengen demand peaks and appointment slots are at their tightest. A June departure means the file should already have opened back in March. The lead time here is not a suggestion; it decides whether you travel."},{"heading":null,"text":"With the monsoon settling at home, the appeal of cool, dry, long-daylight Europe is at its strongest. The earlier the planning, the calmer the trip. Start while others are still deciding."}],"flightsVisas":[{"heading":null,"text":"Book flights early. June is the highest-demand departure of the year, and seats, premium cabins especially, must be secured months out. Award space to Europe thins to almost nothing in this window. Your advisor watches for it and holds it for you the moment it surfaces."},{"heading":null,"text":"Visa lead time. Schengen appointments are scarcest in the summer rush, so the visa process starts very early. Your advisor typically opens the file around three months ahead, in March, to keep your dates safe. Begin late and the calendar, not your plans, decides when you travel."},{"heading":null,"text":"The principle. Visa timelines and requirements change. We confirm the current position for your passport and route before you commit, and we file early enough that the paperwork never decides your dates."}],"pull":"While the rains close in at home, you are where the day refuses to end."},{"no":7,"code":"Jul","name":"July","heading":{"text":"Go in July.","accent":"July"},"lede":"The monsoon settles in at home. So we look the other way, to dry-season safari, to the high Alps in full summer, to the islands at their sunniest.","statement":"When it rains at home, go where it's dry.","note":"As the monsoon arrives across much of India, think the other way round. Let the rest of the world hand you its best weather.","intro":"The southern hemisphere is deep in its dry winter, the finest window for safari, when the bush thins and the animals gather at the water. The Alps are in full summer, cool and green at altitude. Bali and Indonesia sit in their driest, brightest spell, and the Nordic days run long and mild. Skip the Mediterranean at its hot, crowded peak, and take the half of the world that July suits best.","where":[{"heading":"South Africa, on safari","text":"This is the heart of the dry season, and the finest game viewing of the year, the bush is sparse, the grass low, and the animals draw to the waterholes where you see them clearly. Make it a bush trip. The Cape is in its cool, wet winter, so let the lowveld and the private reserves be the journey. Crisp mornings, bright days, generous sightings."},{"heading":"The Alps in high summer","text":"Switzerland, the Italian Dolomites, the French and Austrian high country are at their gentlest now, wildflower meadows, walking trails, glacial lakes, and a warmth the altitude keeps from ever turning heavy. It is the clean answer to the monsoon: clear air, long light, cool nights. A few days in a mountain village set you right."},{"heading":"Bali & Indonesia","text":"The dry season is at its best, reliable sun, lower humidity, and the kind of settled weather that makes the islands feel easy. The surf is good, the rice terraces are luminous, and Bali, Lombok and the islands beyond all welcome you. It reads beautifully against the rains back home."},{"heading":"Scandinavia & the Nordics","text":"The far north is in its brief, bright summer: daylight that stretches deep into the evening, mild temperatures, and a landscape at its greenest. The Norwegian fjords, the Swedish archipelago and the Nordic capitals are all at their summer best, open, unhurried, quietly spectacular."}],"avoid":[{"heading":null,"text":"The Mediterranean, the Amalfi Coast, the Greek islands, the Riviera, is at peak crush and peak prices through July and August. It is glorious, but you will share it. If you can hold the dates, September gives you the same warmth and a fraction of the crowd."},{"heading":null,"text":"The Gulf and the desert are dangerously hot now, daytime heat that keeps you indoors and makes the dunes best left for the cooler months."},{"heading":null,"text":"The Indian Ocean, the Maldives and Seychelles, enters its wetter, breezier spell; still possible, but not the glassy, flawless season it offers earlier in the year."}],"indianAngle":[{"heading":null,"text":"The summer school break tails off through July, though the exact week varies widely by board and region, worth confirming your own calendar before you fix dates."},{"heading":null,"text":"It is still a family-travel month, but Europe is at its most crowded and most expensive; a counter-seasonal long-haul to South Africa or Bali often gives better value and far better weather than the Mediterranean."},{"heading":null,"text":"The monsoon brings its own season of weddings and gatherings at home, easy to fold a short escape around a quieter weekend. Tell us how your month is shaped."}],"flightsVisas":[{"heading":null,"text":"Mind the peak. July is high summer for Europe, and fares to the continent run at their dearest, booked well ahead, they soften a little, but the value this month lies elsewhere. Routes the other way, to South Africa and Bali, are quieter and kinder on price. Your advisor weighs the trade for your dates."},{"heading":null,"text":"Visa lead time. South Africa requires a visa for Indian passport holders, and this is its busy inbound season, so processing runs longer, your advisor starts early, typically a couple of months out, to keep your dates safe. Indonesia's e-VOA is quick to arrange for Bali, but the South Africa paperwork is the one to begin in good time."},{"heading":null,"text":"The principle. Visa timelines and requirements change; we confirm the current position for your passport and route before you commit, and file early enough that the paperwork never decides your dates."}],"pull":"While the rains close in at home, you are somewhere the sky stays open."},{"no":8,"code":"Aug","name":"August","heading":{"text":"Go in August.","accent":"August"},"lede":"The rains hold at home. So this is the month to go the other way: the great migration in full theatre, cool mountain air, and the long northern light.","statement":"Leave the rains behind.","note":"With much of India under cloud and rain, August rewards the traveller who looks outward, to drier, cooler, more dramatic ground.","intro":"While the monsoon settles in at home, much of the world is having a fine month. East Africa's plains are alive with the great migration. The high Alps are in clear summer. The Nordic days are still long and mild, and Bali holds steady in its dry season. Above all, a month to travel against the weather at home, towards open skies and cooler air.","where":[{"heading":"East Africa, Kenya & Tanzania","text":"Around this time the great wildebeest migration is typically at one of its most dramatic stages, though the exact timing shifts with the rains each year. The plains of the Mara and the Serengeti come into their own. River crossings, vast herds, and predators close at hand. This is safari at its fullest."},{"heading":"The high Alps, Switzerland & Italy","text":"Summer in the mountains is at its clearest. Long walking days, alpine lakes warm enough to swim, and cool air that feels like relief after the plains. The grand lakeside towns and high passes are open and green. A clean, quiet escape from the rains."},{"heading":"Scandinavia & the Nordics","text":"The far north is still in its long, mild summer. Light evenings, calm fjords, and quiet archipelagos. The summer cities are at their liveliest before autumn turns. Go now, before the days shorten and the season folds."},{"heading":"Bali & Indonesia","text":"The dry season continues through August, with reliable sun, gentle warmth, and the surf in good order. Closer than the long-haul options and easy on a short break, it makes a dependable Independence-week choice. Sea, rice terraces, and a shorter flight home."}],"avoid":[{"heading":null,"text":"The Mediterranean, Italy, Greece, Spain, is at peak August crush and price, and in places the locals are away and parts of town simply close. Lovely, but not at its most graceful this month."},{"heading":null,"text":"The Gulf and Arabia sit in extreme summer heat. The desert and the city are both punishing by day. Save the dunes for the cooler months."},{"heading":null,"text":"Parts of the Indian Ocean can be in their wetter, windier spell now. The islands are still beautiful, but the conditions are less settled than in the dry season."}],"indianAngle":[{"heading":null,"text":"Independence Day mid-month often opens a reliable long-weekend window. A natural moment for both a short hop and a longer escape, so demand around it tends to spike."},{"heading":null,"text":"School is generally back in session across much of India by August, though terms vary by region. So the month leans more towards couples and shorter trips than family travel."},{"heading":null,"text":"Because the long weekend is popular, the seats and the stays move early. Settle the window well ahead and you travel calmly, rather than scrambling for what is left."}],"flightsVisas":[{"heading":null,"text":"Book flights early. Demand spikes around the Independence Day long weekend, so fares and good seats are best secured well ahead rather than left to the last weeks. Your advisor watches the routes that matter and holds the window before it tightens."},{"heading":null,"text":"Visa lead time. East Africa, Kenya and Tanzania, requires visas for Indian passport holders, and arrangements are smoothest when begun early. Your advisor starts well in advance, so the paperwork never decides your dates. The Nordics and the Alps sit within the Schengen process, which also rewards an early start in a busy season."},{"heading":null,"text":"Lodges, a year out. Migration-season camps and the finest safari lodges often book close to a year ahead. For an August departure, the earlier the stays are held, the better. We confirm current requirements for your passport and route before you commit."}],"pull":"Home stays under the rains. You are out where the horizon goes on forever."},{"no":9,"code":"Sep","name":"September","heading":{"text":"Go in September.","accent":"September"},"lede":"The quiet return. Greece and Italy without the August crowds, the sea still warm, the light turning gold. The month for those who know.","statement":"The crowds go. The warmth stays.","note":"The peak of summer has passed and the coast quietens. When those who know go back to the Mediterranean, before the festival season at home.","intro":"As the monsoon withdraws over India, southern Europe enters its gentlest stretch. The August holidaymakers have gone home, yet the Aegean and the Tyrrhenian are still warm enough to swim. The days are bright and unhurried, and rates ease from their high-summer peak. The same coast you might have chosen in July, returned to you quieter and more generous.","where":[{"heading":"Greece & the islands","text":"The crowds have thinned and the ferries run easy again, yet the Aegean holds its summer warmth well into the month. Santorini, the Cyclades and the quieter Dodecanese feel like themselves again, long, soft evenings and a table whenever you want one. For many who know the islands, this is their finest month."},{"heading":"Italy","text":"The Amalfi Coast, Tuscany and the northern lakes settle into a golden early autumn, the sea still warm, the light softer, the day-trippers fewer. It is harvest season inland, the vineyards turning and the first new wine, and the coast at a pace made for long lunches."},{"heading":"Spain & Portugal","text":"Late-summer warmth without the peak-August heat or the queues, the Andalusian and Algarve coasts still made for the water, the cities cool and walkable again. Madrid, Lisbon and the San Sebastián table all reward a September visit, with the sea holding its temperature into October."},{"heading":"Croatia & the Adriatic","text":"The Dalmatian coast is at its calm best once the August rush has gone. The sea stays warm and still, Dubrovnik and Hvar quieten, and a private boat between the islands becomes the slow pleasure it was meant to be. Settled weather and softer light make this the coast's finest spell."}],"avoid":[{"heading":null,"text":"The Gulf and the Arabian deserts are cooling, but early September can still run hot and humid, pleasant by late evening, less so by day. Give the dunes another month or two."},{"heading":null,"text":"The Indian Ocean, the Maldives and the surrounding atolls, is in a transitional, often wetter phase early in the month, with showers possible. The water is warm, but the reliably dry season has not yet arrived."},{"heading":null,"text":"The far-northern latitudes are losing their long summer daylight. Scandinavia and the Arctic edge feel autumnal now, and the midnight sun has passed for the year."}],"indianAngle":[{"heading":null,"text":"School is firmly back in session, so September belongs to couples and unhurried travellers, quieter resorts, easier tables and a coast that feels grown-up rather than crowded."},{"heading":null,"text":"It sits just before the Diwali peak, which makes it a sensible value window. A Mediterranean September, booked now, costs noticeably less than the festival fortnight that follows."},{"heading":null,"text":"Depending on how the dates fall, a long weekend or two can open up mid-month, enough for a short, well-timed escape before the festive season takes hold."}],"flightsVisas":[{"heading":null,"text":"Book flights before the festival run-up. Shoulder-season fares to Europe are kinder than high summer, but the Diwali run-up pushes October prices up sharply. A September departure, secured before that climb begins, is where the value sits. Your advisor watches the cabin and the award space for you."},{"heading":null,"text":"Visa lead time. Greece, Italy, Spain, Portugal and Croatia are all Schengen for Indian passport holders, and a September trip should have been filed months earlier to be safe. Your advisor starts early, well ahead of the appointment crunch, so the paperwork never decides your dates."},{"heading":null,"text":"The principle. Visa requirements and processing times change. We confirm the current position for your passport and route before you commit, and begin in good time, so the timeline is never the thing standing between you and the trip."}],"pull":"The same coast you love, returned to you quieter. And the sea still warm."},{"no":10,"code":"Oct","name":"October","heading":{"text":"Go in October.","accent":"October"},"lede":"The first turn of autumn. Japan's earliest colour, the Arabian heat breaking, the Indian Ocean drying out. The warmest month of the festive year.","statement":"The season turns, gently.","note":"The month the heat lets go. With Diwali falling around now, it is also the busiest travel window of the season. The plans made early are the plans kept.","intro":"Home is at its kindest, the monsoon behind it, the cold not yet here. Abroad, the world settles. Japan finds its first autumn colour in the north. Jordan and Oman shed the summer heat. The Indian Ocean islands begin to dry into their good season. The festival of lights falls around now, so the calendar fills fast. The best months are the ones planned furthest ahead.","where":[{"heading":"Japan","text":"Early autumn is among the finest times to be here. Mild days, clear skies, and the first colour beginning in the north. The full foliage peaks later, closer to November, so this is the quiet prelude. Tokyo and Kyoto are at their most walkable, the gardens slowly turning."},{"heading":"Jordan & Oman","text":"The summer heat breaks and the desert opens up again. Petra and the silence of Wadi Rum reward an October visit, and Oman's coast and mountains return to comfortable temperatures. This is the start of the long, kind season for Arabia, warm by day, cool once the sun drops."},{"heading":"The Maldives & Indian Ocean","text":"The islands are turning toward the drier season. The sun grows more reliable, the water settles into calm. Early in the month a passing shower is still possible, but the trend is firmly toward clear skies, a fine, improving window for the overwater villa, before the high-season crowds arrive."},{"heading":"Türkiye & the eastern Mediterranean","text":"A warm, golden autumn lingers along this coast while the summer crowds have thinned. Istanbul is at its most pleasant for walking, and the shoreline still holds enough warmth for the sea. October gives you the Mediterranean's beauty without its August intensity."}],"avoid":[{"heading":null,"text":"Northern and Alpine Europe are sliding into shorter days and a real chill. Best left for now, unless you are going expressly to chase the autumn colour."},{"heading":null,"text":"The wider Mediterranean cools and quietens as the month goes on. The early weeks still hold warmth; the later ones can feel like the season packing up."},{"heading":null,"text":"Very high-altitude journeys grow less dependable as the weather turns. The trekking windows narrow, and conditions become harder to promise."}],"indianAngle":[{"heading":null,"text":"Diwali falls around this period, one of the busiest travel windows of the year. Long-haul journeys and the nearer escapes alike rise in price and fill weeks ahead. Booking early is not caution; it is the only way to hold the dates you want."},{"heading":null,"text":"This is a family-and-celebration window, so the best suites and connecting rooms go first. If you are travelling as a group, the rooms that keep everyone together are worth claiming long before the festival."},{"heading":null,"text":"Demand on flights climbs sharply in the run-up to the festival. The trips that go well this month are set in motion early. Your advisor watches the calendar, so the celebration sets the pace, not the logistics."}],"flightsVisas":[{"heading":null,"text":"Book flights early. Diwali-period flights book out and inflate well before departure. Secure them ahead of time, ideally a couple of months out. Premium-cabin space in this window is among the scarcest of the year; your advisor watches it and moves the moment it opens."},{"heading":null,"text":"Visa lead time. Japan and Jordan require visas for Indian passport holders, and the festive-season rush lengthens processing. Your advisor starts early to keep your dates safe. The Maldives is visa-on-arrival, so the islands stay simple; it is Japan and Jordan that reward an early start."},{"heading":null,"text":"The principle. Visa requirements and timelines change. We confirm the current position for your passport and route before you commit, and file early enough that the paperwork never decides your dates."}],"pull":"As home lights its lamps, the world abroad turns warm and golden."},{"no":11,"code":"Nov","name":"November","heading":{"text":"Go in November.","accent":"November"},"lede":"The dry season returns to the tropics. The Indian Ocean turns clear again, the Emirates open up outdoors, and the air at home cools.","statement":"The skies clear, the seas settle.","note":"The rains have lifted across much of the tropics and the heat has broken in the Gulf. The open, easy start of the warm-weather season.","intro":"Across the Indian Ocean and South-East Asia the wet months are receding, leaving calmer water and steadier sun. The Gulf cools enough to be lived outdoors, day and night. At home the weather turns crisp. A fine moment to slip away somewhere the water is warm and the light is long, before the December rush takes hold.","where":[{"heading":"The Maldives & Seychelles","text":"The dry season is firmly setting in, returning the water to its clear, calm best and the sun to something close to reliable. This is the overwater villa as it should be: glassy lagoons, easy diving, long unbroken days. Conditions improve through the month as the last of the rains fall away."},{"heading":"The UAE","text":"The summer heat breaks and the outdoor season opens: the desert pleasant rather than punishing, the beaches inviting, the city comfortable from morning to night. A short flight from India makes it the natural cool-weather escape. Evenings on a terrace, or out among the dunes, are at their finest now."},{"heading":"Vietnam, the centre and south","text":"The country's centre enters its drier window while the south stays warm and dry: Hoi An's lantern-lit lanes, the Mekong's slow waterways, the long coast. Regional weather varies and the centre can still see late showers, so your advisor times the route to the forecast. It rewards an unhurried, well-planned itinerary."},{"heading":"Thailand & the Andaman","text":"The dry season is opening up as the wet months draw to a close, and the seas around the islands begin to calm and clear. The Andaman coast and its beaches return to form: warm, bright, increasingly settled. This is the start of the long, fine stretch that runs through the winter."}],"avoid":[{"heading":null,"text":"Northern and Alpine Europe are now cold and short on daylight, worth it only for the very first snow, or for the early Christmas markets that open late in the month, and even then the weather can be grey."},{"heading":null,"text":"The Mediterranean, Greece, Italy, the Riviera, is firmly out of season: cool, often wet, with much of the coastal and island infrastructure closed for the winter. Keep it for the spring."},{"heading":null,"text":"The high northern latitudes are dark and short-dayed; beautiful for the aurora, perhaps, but otherwise this isn't the month for them."}],"indianAngle":[{"heading":null,"text":"November can overlap the tail of Diwali, the timing shifts year to year, so the earliest days may still carry festival-peak pricing on seats and rooms. Travel once it has passed and the value improves."},{"heading":null,"text":"After the festival settles, the rest of the month is a quiet, good-value window before the December break draws everyone away again, calmer resorts, easier tables, gentler fares."},{"heading":null,"text":"School is in session, so November leans toward couples and shorter trips rather than family groups. The occasional long weekend can make for a neat three- or four-day escape."}],"flightsVisas":[{"heading":null,"text":"Book flights ahead. Post-Diwali fares ease, but the December peak is already looming on the horizon, so the best seats and value go to those who book early rather than wait. Premium-cabin space to the Maldives and the Gulf tightens as the winter approaches; your advisor watches it for you."},{"heading":null,"text":"Visa lead time. The Maldives is visa-on-arrival, the UAE e-visa is quick, and Vietnam and Thailand offer straightforward e-visa or visa-on-arrival routes for Indian passport holders. Where anything longer is involved, your advisor starts early so the paperwork is never the thing that decides your dates."},{"heading":null,"text":"The principle. Visa timelines and requirements change; we confirm the current position for your passport and route before you commit, and file in good time so your travel is never held up by a form."}],"pull":"The rains have gone. The crowds have not yet arrived. The water is quiet, and waiting."},{"no":12,"code":"Dec","name":"December","heading":{"text":"Go in December.","accent":"December"},"lede":"The festive break, and the busiest stretch of the travel year. The right time for first snow, for the Southern summer, for the Gulf at its finest.","statement":"Snow, or the Southern sun.","note":"Schools close, the festive break opens, and the whole world moves at once. The most in-demand month to be away.","intro":"Home turns cool and festive while two seasons run at once elsewhere. The Alps welcome the first skiers and the mountain villages light up. Far to the south, Australia, New Zealand and the Cape settle into high summer. The Gulf is at its most agreeable, the Indian Ocean glassy and dry. Everyone wants the same fortnight, so this is the month to plan furthest ahead.","where":[{"heading":"The Alps","text":"Ski season opens across Switzerland, France, Austria and Italy, and the snow builds steadily as the month turns toward Christmas. Early-season cover varies year to year, so the higher resorts tend to be the safer bet for reliable skiing. Either way, the festive mountain villages, lights, markets, woodsmoke, are reason enough to go."},{"heading":"The UAE & Oman","text":"The Gulf is at its finest now: warm, easy sun by day and genuinely cool evenings, with desert and beach both in their element. Short flights from India make this the simplest festive escape of all. Mornings in the dunes, afternoons by the water, nothing rushed."},{"heading":"Australia & New Zealand","text":"High Southern summer, long daylight, warm beaches, and the vineyards in full swing. It is also the height of the local holiday season, so flights, lodges and the best tables go quickly. Book early and you have two countries at their most generous."},{"heading":"The Maldives & Indian Ocean","text":"Peak dry season brings calm, clear water and dependable sun, the islands at their most flawless. This is the great festive-and-New-Year destination, and with that comes the highest demand of the year. The finest water villas are held many months out, so early intent matters most here."}],"avoid":[{"heading":null,"text":"Anything you can't book far ahead. The festive fortnight strips availability everywhere at once, and a late plan usually means a compromise, on the flight, the room, or both."},{"heading":null,"text":"The Mediterranean is firmly out of season: cool, often wet, and much of the coast and islands shuttered for winter. Hold it for the warmer shoulder months."},{"heading":null,"text":"Northern Europe, beyond the Christmas-market charm, is cold and dark, with very short days. Lovely for a long festive weekend in the cities; less so for a longer stay chasing daylight."}],"indianAngle":[{"heading":null,"text":"The Christmas–New-Year break is the busiest travel window of the year, when alpine snow, the Southern summer and the Gulf all spike together. Plan for it furthest ahead, six months is not too early."},{"heading":null,"text":"Families travel in force this fortnight, so the best ski chalets, water villas and connecting suites go first and fastest of any month. Early intent is the difference between the right room and whatever is left."},{"heading":null,"text":"If your dates are fixed by the school calendar, settle the cabin and the stay before the rooms tighten. A little flexibility on either side of the peak eases both price and choice."}],"flightsVisas":[{"heading":null,"text":"Book flights early. This is the highest-demand window of the year, and seats, especially in the premium cabins to the Maldives, the Alps and the Antipodes, must be secured months out, often half a year ahead. Your advisor watches the routes and holds the space before it goes."},{"heading":null,"text":"Visa lead time. The Alps sit within Schengen, and Australia and New Zealand require visas for Indian passport holders, and peak-season processing runs longer. Your advisor starts early to keep your dates safe. The Maldives is visa-on-arrival and the UAE e-visa is quick, but the European and Antipodean routes are the ones to begin in good time."},{"heading":null,"text":"The principle. Visa timelines and requirements change. We confirm the current position for your passport and route before you commit, and file early enough that the paperwork never decides your dates."}],"pull":"The year winds down at home. You're already somewhere it has only just begun."}]

